INSERT INTO use_cases ("id", "org_id", "workspace_id", "name", "description", "status", "stage", "tier", "patterns", "stack", "scope_lock", "methodology_version", "created_by", "created_at", "updated_at", "context_updated_at", "red_team_at", "business_function", "owner_name", "owner_email", "technical_owner", "sponsor", "lifecycle", "af_environment") VALUES ('6cd7fa45-ee1a-4910-9769-e8f1de6acd5e', '00000000-0000-4000-a000-0000000000de', NULL, 'Customer Onboarding Workflow Agent', 'We''ve enabled GitHub Copilot for our software engineering team. It has access to our private repositories including proprietary application code, internal libraries, and infrastructure-as-code configurations. Developers use it for code suggestions, auto-completion, and reviewing pull requests. It doesn''t execute code, deploy anything, or access production systems — it only suggests within the IDE. We''re on Azure DevOps with Entra ID for identity.', 'archived', 'controls', 2, '["Copilot","Developer AI tool","Embedded vendor AI"]'::jsonb, '{"other":"","products":[{"name":"Azure","category":"cloud","services":[]},{"name":"Microsoft Entra ID","category":"identity","services":[]},{"name":"Microsoft Defender","category":"edr","services":[]},{"name":"Microsoft Sentinel","category":"siem","services":[]},{"name":"Jira","category":"itsm","services":[]},{"name":"Cloudflare","category":"network","services":[]},{"name":"Terraform","category":"iac_cicd","services":[]},{"name":"GitHub","category":"code","services":[]}]}'::jsonb, '{"triggers":[{"id":"T1","newTier":4,"trigger":"Copilot is given ability to auto-merge PRs, commit code, or trigger CI/CD pipelines without developer action"},{"id":"T2","newTier":4,"trigger":"Copilot or a connected agent gains ability to execute code, run tests, or interact with production/staging environments"},{"id":"T3","newTier":3,"trigger":"PR review comments are posted autonomously and treated as blocking or authoritative review (i.e., substituting for human code review)"},{"id":"T4","newTier":3,"trigger":"Copilot access is extended to repositories containing customer data, PII, or regulated data (e.g., health, financial records)"},{"id":"T5","newTier":"2 (re-review required)","trigger":"Data retention or model training opt-out is reversed, or vendor data handling terms change materially"},{"id":"T6","newTier":3,"trigger":"Copilot is integrated into automated workflows that generate customer-facing artifacts (e.g., API documentation published externally)"}]}'::jsonb, NULL, '00000000-0000-4000-b000-0000000000de', '2026-06-08T08:13:00.761522+00:00', '2026-06-08T08:18:33.368+00:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'prod') ON CONFLICT DO NOTHING;
INSERT INTO use_cases ("id", "org_id", "workspace_id", "name", "description", "status", "stage", "tier", "patterns", "stack", "scope_lock", "methodology_version", "created_by", "created_at", "updated_at", "context_updated_at", "red_team_at", "business_function", "owner_name", "owner_email", "technical_owner", "sponsor", "lifecycle", "af_environment") VALUES ('b6e7d0a8-46e0-45bb-bd45-131f811e3c22', '00000000-0000-4000-a000-0000000000de', NULL, 'Marketing Blog Content Drafting Assistant', 'We''re giving our marketing team access to ChatGPT Team to help draft blog posts, social media captions, and newsletter copy. It only uses publicly available information — no internal data, no customer data, no proprietary strategy documents. The team writes the prompts themselves and always reviews and edits the output before publishing. No integrations with any internal systems.', 'active', 'operate', 2, '["Copilot","Internal LLM application"]'::jsonb, '{"other":"","products":[{"name":"AWS","category":"cloud","services":["CloudTrail","CloudWatch","GuardDuty","Security Hub","S3","KMS"]},{"name":"On-premises","category":"cloud","services":[]},{"name":"Okta","category":"identity","services":[]},{"name":"LangChain","category":"agent_framework","services":[]},{"name":"CrowdStrike","category":"edr","services":[]},{"name":"Splunk","category":"siem","services":[]},{"name":"ServiceNow","category":"itsm","services":[]},{"name":"Zscaler","category":"network","services":[]},{"name":"Terraform","category":"iac_cicd","services":[]},{"name":"GitHub","category":"code","services":[]},{"name":"Databricks","category":"data","services":[]},{"name":"Drata","category":"grc","services":[]}]}'::jsonb, '{"triggers":[{"id":"T1","newTier":2,"trigger":"Staff begin pasting internal data, customer data, or pre-release information into prompts — either by policy change or observed behavior"},{"id":"T2","newTier":3,"trigger":"Output is published without meaningful human review (e.g. direct-to-publish workflow, automated posting)"},{"id":"T3","newTier":4,"trigger":"Tool is connected to CMS, email platform, or social media scheduler via API or plugin"},{"id":"T4","newTier":3,"trigger":"Content generated covers regulated domains (financial promotions, health claims, legal disclosures) where published output carries compliance obligations"},{"id":"T5","newTier":3,"trigger":"Use expands beyond marketing to HR communications, investor relations, or customer support responses"}]}'::jsonb, NULL, '00000000-0000-4000-b000-0000000000de', '2026-06-08T04:37:42.934007+00:00', '2026-06-12T03:48:59.353+00:00', NULL, '2026-07-17T11:03:48.353+00:00', 'Marketing', 'Demo User', NULL, NULL, NULL, 'production', 'prod') ON CONFLICT DO NOTHING;
INSERT INTO use_cases ("id", "org_id", "workspace_id", "name", "description", "status", "stage", "tier", "patterns", "stack", "scope_lock", "methodology_version", "created_by", "created_at", "updated_at", "context_updated_at", "red_team_at", "business_function", "owner_name", "owner_email", "technical_owner", "sponsor", "lifecycle", "af_environment") VALUES ('159c61b4-30e3-40d4-88f0-f5a4b1d66b1b', '00000000-0000-4000-a000-0000000000de', NULL, 'Customer Onboarding Workflow Agent', 'We''re building an AI agent that handles new customer onboarding. It reads the signed contract from Salesforce, extracts key terms and SLA requirements, creates the customer workspace in our platform, provisions user accounts in Okta, generates the welcome email with credentials, creates the onboarding project in Jira with pre-defined task templates, and schedules the kickoff call by checking availability in Google Calendar. A human reviews the extracted contract terms before the agent proceeds, but once approved, the agent executes all the downstream steps automatically. It runs on LangGraph with GPT-4o, hosted on GCP, and has API access to Salesforce, Okta, Jira, Google Workspace, and our internal provisioning system.', 'active', 'operate', 5, '["Agent","Workflow automation","Action-capable AI"]'::jsonb, '{"other":"","products":[{"name":"GCP","category":"cloud","services":["Cloud KMS","GKE"]},{"name":"LangChain","category":"agent_framework","services":[]},{"name":"Okta","category":"identity","services":[]},{"name":"CrowdStrike","category":"edr","services":[]},{"name":"Google Chronicle","category":"siem","services":[]},{"name":"Terraform","category":"iac_cicd","services":[]},{"name":"GitHub","category":"code","services":[]},{"name":"Jira","category":"itsm","services":[]},{"name":"Google Workspace","category":"identity","services":[]},{"name":"Salesforce","category":"data","services":[]}]}'::jsonb, '{"triggers":[{"id":"T1","newTier":"5 — re-review required","trigger":"Okta API permissions expanded to allow modification or deactivation of existing accounts beyond new provisioning"},{"id":"T2","newTier":"5 — re-review required","trigger":"Human approval gate removed or auto-approved (e.g. for ''standard'' contracts)"},{"id":"T3","newTier":"5 — re-review required","trigger":"Agent gains write access to existing Salesforce records or can modify contract data"},{"id":"T4","newTier":"5 — re-review required","trigger":"Agent given ability to self-correct or retry failed steps without human intervention"},{"id":"T5","newTier":"5 — re-review required","trigger":"Scope expanded to handle contract amendments, renewals, or customer offboarding"},{"id":"T6","newTier":"5 — re-review required","trigger":"Agent begins handling regulated customer types (financial services, healthcare, government)"}]}'::jsonb, NULL, '00000000-0000-4000-b000-0000000000de', '2026-06-08T08:19:08.843054+00:00', '2026-06-12T03:50:30.119+00:00', NULL, NULL, 'Customer Relations', 'Demo User', NULL, NULL, NULL, NULL, 'prod') ON CONFLICT DO NOTHING;
INSERT INTO use_cases ("id", "org_id", "workspace_id", "name", "description", "status", "stage", "tier", "patterns", "stack", "scope_lock", "methodology_version", "created_by", "created_at", "updated_at", "context_updated_at", "red_team_at", "business_function", "owner_name", "owner_email", "technical_owner", "sponsor", "lifecycle", "af_environment") VALUES ('5576a726-ad6e-4da7-b9d9-6ca3ff8a030e', '00000000-0000-4000-a000-0000000000de', NULL, 'Meeting Note Cleanup Assistant', 'Our team uses ChatGPT to clean up and format their personal meeting notes — fixing grammar, organizing bullet points, and summarizing action items. They only paste their own handwritten notes, no recordings, no transcripts, no internal documents. Just tidying up what they already wrote', 'active', 'operate', 2, '["Copilot","Internal LLM application"]'::jsonb, '{"other":"","products":[{"name":"OpenAI API","category":"ai_platform","services":[]}]}'::jsonb, '{"triggers":[{"id":"T1","newTier":3,"trigger":"Outputs are saved into shared systems (wikis, project tools, shared drives) and treated as official meeting records"},{"id":"T2","newTier":3,"trigger":"Usage expands to include pasting actual meeting transcripts, recordings, or internal documents rather than just personal notes"},{"id":"T3","newTier":4,"trigger":"Tool is integrated with calendar, email, or collaboration platforms to auto-ingest or auto-distribute notes"},{"id":"T4","newTier":4,"trigger":"Action items generated by the AI are automatically routed to task management systems or trigger notifications"}]}'::jsonb, NULL, '00000000-0000-4000-b000-0000000000de', '2026-06-08T13:34:55.932971+00:00', '2026-06-12T03:55:29.82+00:00', NULL, '2026-06-11T13:43:18.07+00:00', 'Company-wide', NULL, NULL, NULL, NULL, NULL, 'prod') ON CONFLICT DO NOTHING;
INSERT INTO use_cases ("id", "org_id", "workspace_id", "name", "description", "status", "stage", "tier", "patterns", "stack", "scope_lock", "methodology_version", "created_by", "created_at", "updated_at", "context_updated_at", "red_team_at", "business_function", "owner_name", "owner_email", "technical_owner", "sponsor", "lifecycle", "af_environment") VALUES ('97cd8230-e2e2-47e4-944a-e5896b5ef796', '00000000-0000-4000-a000-0000000000de', NULL, 'Automated Contract Review and Compliance', 'This system automatically scans, analyzes, and flags risks across thousands of corporate contracts, legal agreements, and vendor documents simultaneously. Instead of legal teams spending hours manually reading through pages of text, the AI instantly detects non-standard clauses, missing regulatory disclosures, expiring dates, and potential financial liabilities. It highlights these critical areas for human review, dramatically reducing legal risks and speeding up business operations.', 'active', 'operate', 3, '["RAG system","Decision-supporting AI","High-impact or regulated AI"]'::jsonb, '{"other":"","products":[{"name":"AWS","category":"cloud","services":["Bedrock"]},{"name":"OpenAI API","category":"ai_platform","services":[]},{"name":"Okta","category":"identity","services":[]},{"name":"Splunk","category":"siem","services":[]},{"name":"Jira","category":"itsm","services":[]},{"name":"Terraform","category":"iac_cicd","services":[]}]}'::jsonb, '{"triggers":[{"id":"T1","newTier":4,"trigger":"AI flags automatically block contract progression, trigger hold statuses, or prevent execution without human initiation"},{"id":"T2","newTier":4,"trigger":"System sends notifications or communications to counterparties, vendors, or external parties based on AI findings"},{"id":"T3","newTier":4,"trigger":"System integrates via API with CLM platforms (e.g., Ironclad, Agiloft) and can create, modify, or update contract records or metadata"},{"id":"T4","newTier":5,"trigger":"AI-generated risk classifications are used as the sole basis for contract approval/rejection without meaningful human legal review"},{"id":"T5","newTier":5,"trigger":"System autonomously determines regulatory compliance status that is relied upon for audit or filing purposes without legal sign-off"},{"id":"T6","newTier":4,"trigger":"Routing function gains ability to reassign contract ownership, modify approval chains, or alter workflow states in downstream systems"}]}'::jsonb, NULL, '00000000-0000-4000-b000-0000000000de', '2026-06-10T03:31:41.229369+00:00', '2026-06-12T03:48:05.806+00:00', NULL, '2026-06-10T17:26:58.26+00:00', 'Legal', 'Demo User', NULL, NULL, NULL, NULL, 'prod') ON CONFLICT DO NOTHING;
INSERT INTO use_cases ("id", "org_id", "workspace_id", "name", "description", "status", "stage", "tier", "patterns", "stack", "scope_lock", "methodology_version", "created_by", "created_at", "updated_at", "context_updated_at", "red_team_at", "business_function", "owner_name", "owner_email", "technical_owner", "sponsor", "lifecycle", "af_environment") VALUES ('caceb4e1-bbcb-4cea-9598-bd15dd0d27d4', '00000000-0000-4000-a000-0000000000de', NULL, 'An internal AI assistant that helps employees answers questions', 'An internal AI assistant that answers basic employee questions using approved, low-sensitivity company FAQs and policy documents, such as travel policy, expense submission, laptop requests, and holiday calendars.', 'active', 'operate', 2, '["Copilot","RAG system","Internal LLM application"]'::jsonb, '{"other":"","products":[{"name":"AWS","category":"cloud","services":["CloudTrail","GuardDuty","Config"]},{"name":"AWS Bedrock","category":"ai_platform","services":[]},{"name":"LangChain","category":"agent_framework","services":[]},{"name":"Okta","category":"identity","services":[]},{"name":"CrowdStrike","category":"edr","services":[]},{"name":"Jira","category":"itsm","services":[]}]}'::jsonb, '{"triggers":[{"id":"T1","newTier":4,"trigger":"Assistant gains ability to initiate transactions or requests on behalf of employees (e.g., submit expense reports, raise IT tickets)"},{"id":"T2","newTier":3,"trigger":"Assistant begins accessing employee-specific data such as personal records, compensation, role information, or employment history"},{"id":"T3","newTier":3,"trigger":"Assistant output is used as an authoritative source for compliance, legal, or HR decisions rather than as informational reference"},{"id":"T4","newTier":3,"trigger":"Document corpus expands to include confidential, sensitive, or regulated content (e.g., HR investigation procedures, legal hold policies, security protocols)"},{"id":"T5","newTier":2,"trigger":"Conversation history is retained long-term and contains employee-identifiable data that could be accessed or exported"}]}'::jsonb, NULL, '00000000-0000-4000-b000-0000000000de', '2026-06-10T15:45:35.047701+00:00', '2026-06-12T03:47:46.782+00:00', NULL, '2026-06-10T17:21:16.084+00:00', 'Company-wide', 'Demo User', NULL, NULL, NULL, NULL, 'prod') ON CONFLICT DO NOTHING;
INSERT INTO use_cases ("id", "org_id", "workspace_id", "name", "description", "status", "stage", "tier", "patterns", "stack", "scope_lock", "methodology_version", "created_by", "created_at", "updated_at", "context_updated_at", "red_team_at", "business_function", "owner_name", "owner_email", "technical_owner", "sponsor", "lifecycle", "af_environment") VALUES ('84c9d8a0-f0da-43ca-8e3a-41c529bfbe9d', '00000000-0000-4000-a000-0000000000de', NULL, 'The Internal Helpdesk Assistant', 'Core Architecture: Retrieval-Augmented Generation (RAG)

Data Ingestion: Company documents (PDFs, wikis, policies) are processed, chunked into smaller text blocks, and converted into numerical formats (embeddings).

Storage: A Vector Database stores these embeddings for rapid semantic searching.

Retrieval: When an employee asks a question, the system searches the database for the document chunks most relevant to the query.

Generation: A Large Language Model (LLM) reads those specific chunks and synthesizes a direct answer based only on the retrieved company data.

Interface: The bot is integrated directly into the platforms employees already use, such as Slack, Microsoft Teams, or an internal portal.', 'active', 'operate', 2, '["RAG system","Internal LLM application","Copilot"]'::jsonb, '{"other":"","products":[{"name":"GCP","category":"cloud","services":["Security Command Center","Cloud KMS","GKE"]},{"name":"LangChain","category":"agent_framework","services":[]},{"name":"Okta","category":"identity","services":[]},{"name":"CrowdStrike","category":"edr","services":[]},{"name":"Datadog","category":"siem","services":[]},{"name":"Terraform","category":"iac_cicd","services":[]},{"name":"Drata","category":"grc","services":[]},{"name":"GitHub","category":"code","services":[]},{"name":"Databricks","category":"data","services":[]},{"name":"Jira","category":"itsm","services":[]}]}'::jsonb, '{"triggers":[{"id":"T1","newTier":4,"trigger":"Assistant gains ability to open tickets, submit IT requests, escalate to agents, or trigger any workflow"},{"id":"T2","newTier":3,"trigger":"Employees begin relying on answers for compliance, HR, legal, or financial decisions without independent verification"},{"id":"T3","newTier":3,"trigger":"Document corpus expands to include restricted/classified data (e.g., M&A documents, security configurations, PII-rich records) without role-based retrieval access controls"},{"id":"T4","newTier":3,"trigger":"Assistant outputs are treated as official or authoritative policy interpretations rather than informational summaries"},{"id":"T5","newTier":3,"trigger":"System is extended to external users (customers, partners, contractors outside the enterprise)"}]}'::jsonb, NULL, '00000000-0000-4000-b000-0000000000de', '2026-06-09T03:10:13.848319+00:00', '2026-06-12T03:48:36.9+00:00', NULL, '2026-06-10T17:25:02.688+00:00', 'Support', 'Demo User', 'demo@community.example', NULL, NULL, NULL, 'prod') ON CONFLICT DO NOTHING;
INSERT INTO use_cases ("id", "org_id", "workspace_id", "name", "description", "status", "stage", "tier", "patterns", "stack", "scope_lock", "methodology_version", "created_by", "created_at", "updated_at", "context_updated_at", "red_team_at", "business_function", "owner_name", "owner_email", "technical_owner", "sponsor", "lifecycle", "af_environment") VALUES ('fc90f117-261f-4c81-bfb3-de7f82437c5c', '00000000-0000-4000-a000-0000000000de', NULL, 'Engineering Code Review Copilot', 'We''ve enabled GitHub Copilot for our software engineering team. It has access to our private repositories including proprietary application code, internal libraries, and infrastructure-as-code configurations. Developers use it for code suggestions, auto-completion, and reviewing pull requests. It doesn''t execute code, deploy anything, or access production systems — it only suggests within the IDE. We''re on Azure DevOps with Entra ID for identity', 'active', 'operate', 2, '["Copilot","Embedded vendor AI","Developer AI tool"]'::jsonb, '{"other":"","products":[{"name":"GCP","category":"cloud","services":["Cloud Functions","Cloud KMS","GKE"]},{"name":"GCP Vertex AI","category":"ai_platform","services":[]},{"name":"Google Workspace","category":"identity","services":[]},{"name":"Palo Alto Cortex","category":"edr","services":[]},{"name":"Datadog","category":"siem","services":[]},{"name":"Jira","category":"itsm","services":[]},{"name":"Cloudflare","category":"network","services":[]},{"name":"Terraform","category":"iac_cicd","services":[]},{"name":"GitHub","category":"code","services":[]},{"name":"PostgreSQL","category":"data","services":[]},{"name":"OneTrust","category":"grc","services":[]}]}'::jsonb, '{"triggers":[{"id":"T1","newTier":4,"trigger":"Copilot gains ability to execute code, run tests, or trigger CI/CD pipelines (e.g., Copilot Workspace or agent mode with tool access)"},{"id":"T2","newTier":3,"trigger":"Copilot PR review comments are posted directly to pull requests without developer intermediation"},{"id":"T3","newTier":3,"trigger":"Copilot is used to generate or influence compliance, security policy, or audit-relevant documentation relied upon in a business process"},{"id":"T4","newTier":3,"trigger":"IaC repositories containing secrets or security configurations are found to be in scope and Copilot cross-suggests those patterns into other repos"},{"id":"T5","newTier":4,"trigger":"Copilot is integrated with GitHub Actions, Azure Pipelines, or other automation that can commit, merge, or deploy code"},{"id":"T6","newTier":"2 (re-review with vendor/supply chain escalation)","trigger":"Training data opt-out is not confirmed or is reversed by vendor policy change"}]}'::jsonb, NULL, '00000000-0000-4000-b000-0000000000de', '2026-06-08T05:27:41.131002+00:00', '2026-06-12T03:50:49.335+00:00', NULL, '2026-06-12T00:44:56.921+00:00', 'Other', 'Demo User', NULL, NULL, NULL, NULL, 'prod') ON CONFLICT DO NOTHING;
INSERT INTO use_cases ("id", "org_id", "workspace_id", "name", "description", "status", "stage", "tier", "patterns", "stack", "scope_lock", "methodology_version", "created_by", "created_at", "updated_at", "context_updated_at", "red_team_at", "business_function", "owner_name", "owner_email", "technical_owner", "sponsor", "lifecycle", "af_environment") VALUES ('655e2baa-9a21-4e1b-8449-d9f8202770a7', '00000000-0000-4000-a000-0000000000de', NULL, 'HR Policy and Employee Relations Copilot', 'An internal AI assistant for HR business partners, people managers, and employee relations teams that helps answer HR policy questions, summarize employee case history, draft manager guidance, and recommend next steps for employee relations scenarios.

The assistant can retrieve information from approved HR policy documents, employee handbooks, benefits guidance, internal knowledge articles, prior HR case notes, and selected HRIS records. It may help draft responses to managers or employees, summarize relevant policy considerations, and suggest escalation paths, but final decisions remain with authorized HR personnel.

This use case is designed as decision support, not autonomous decision-making. The AI should not independently approve, deny, discipline, terminate, promote, rate performance, or make employment decisions.

Example Business Requirements
1. Policy and Knowledge Retrieval

The assistant should retrieve answers only from approved HR policy sources, employee handbooks, benefits documentation, and HR knowledge articles.

2. Employee Context Access

The assistant may access limited employee context from HR systems where permitted, such as role, location, employment type, manager, tenure, and relevant case metadata.

3. Employee Relations Case Support

The assistant should summarize prior case notes, identify relevant policy areas, and help HR teams prepare for employee relations discussions.

4. Drafting Support

The assistant may draft manager guidance, employee communications, investigation summaries, or escalation notes, but all drafts must be reviewed and approved by an authorized HR user before use.

5. Human Decision Ownership

The assistant must not make final employment decisions. Decisions involving discipline, termination, promotion, compensation, accommodation, grievance handling, or performance outcomes must remain with named human owners.

6. Sensitive Data Boundaries

The assistant must apply stricter controls for sensitive HR data, including health information, accommodation requests, grievance details, investigation notes, compensation data, protected characteristics, and legal-sensitive content.

7. Role-Based Access

Users should only receive AI responses based on the HR data and policy content they are authorized to access. Managers should not be able to retrieve restricted HR case notes or confidential employee relations details.

8. Output Guardrails

The assistant should avoid unsupported legal conclusions, discriminatory recommendations, speculative judgments, or advice that could be interpreted as final employment action.

9. Escalation Rules

The assistant should escalate high-risk scenarios to HR, legal, privacy, or employee relations specialists, including cases involving harassment, discrimination, retaliation, workplace safety, protected leave, accommodations, or termination.

10. Audit and Evidence

The system should log prompts, retrieved sources, generated outputs, user approvals, edits, escalations, and final human decisions where appropriate.

11. Assurance Testing

The assistant should be tested for hallucination, policy misinterpretation, sensitive data exposure, role-based access failures, bias, unsafe recommendations, and overreliance by managers or HR users.

12. Deployment Scope

Initial deployment should be limited to HR business partners and employee relations specialists before expanding to people managers or broader employee self-service use.', 'active', 'controls', 4, '["Copilot","RAG system","Internal LLM application","Decision-supporting AI","High-impact or regulated AI"]'::jsonb, '{"other":"","products":[{"name":"Workday HCM","category":"identified","services":[],"capability":"other"},{"name":"HR Service Delivery","category":"identified","services":[],"capability":"itsm"},{"name":"SharePoint Online","category":"identified","services":[],"capability":"other"},{"name":"Teams","category":"identified","services":[],"capability":"other"},{"name":"Entra ID","category":"identified","services":[],"capability":"identity"},{"name":"Azure OpenAI Service","category":"identified","services":[],"capability":"ai_platform"},{"name":"Azure AI Search","category":"identified","services":[],"capability":"ai_platform"},{"name":"Microsoft Sentinel","category":"identified","services":[],"capability":"siem"},{"name":"Splunk SIEM (Enterprise Security)","category":"identified","services":[],"capability":"siem"},{"name":"Purview Information Protection","category":"identified","services":[],"capability":"data"},{"name":"OneTrust GRC & Security Assurance Cloud","category":"identified","services":[],"capability":"grc"}]}'::jsonb, '{"triggers":[{"id":"T1","newTier":4,"trigger":"HRIS integration changes from read-only to read-write, enabling record creation or modification"},{"id":"T2","newTier":4,"trigger":"Assistant gains ability to send communications directly to employees or managers without a manual copy/send step"},{"id":"T3","newTier":4,"trigger":"Escalation recommendations are wired to automatically create tickets, route cases, or notify specialists without human initiation"},{"id":"T4","newTier":4,"trigger":"Expansion to employee self-service where employees can query their own case status or submit concerns through the assistant"},{"id":"T5","newTier":5,"trigger":"Assistant outputs are used as direct inputs to employment decisions (performance ratings, termination approvals, accommodation determinations) without meaningful independent review"},{"id":"T6","newTier":3,"trigger":"Access scope expands to include full investigation files, legal hold materials, or litigation-sensitive content"},{"id":"T7","newTier":4,"trigger":"Role-based access controls fail or are bypassed, allowing managers to access restricted ER case notes or protected data"}]}'::jsonb, NULL, '00000000-0000-4000-b000-0000000000de', '2026-06-12T05:01:54.092993+00:00', '2026-07-04T10:53:14.391+00:00', '2026-06-12T05:17:50.977+00:00', '2026-07-03T02:42:21.943+00:00', 'HR', 'Demo User', NULL, 'Demo User', 'Demo User', 'pilot', 'prod') ON CONFLICT DO NOTHING;
