INSERT INTO questions ("id", "org_id", "use_case_id", "stage", "text", "assignee", "answer", "answered_by", "status", "created_at") VALUES ('ebadcd1b-be9a-4389-8744-7a946b70f8e8', '00000000-0000-4000-a000-0000000000de', 'caceb4e1-bbcb-4cea-9598-bd15dd0d27d4', 'questions', 'When a source policy document is updated, how quickly does the RAG index reflect that change — is re-indexing triggered automatically on document save, run on a schedule, or initiated manually?', NULL, 'its done manually', '00000000-0000-4000-b000-0000000000de', 'answered', '2026-06-10T15:50:42.589714+00:00') ON CONFLICT DO NOTHING;
INSERT INTO questions ("id", "org_id", "use_case_id", "stage", "text", "assignee", "answer", "answered_by", "status", "created_at") VALUES ('2f6ea4c4-243a-4ca1-a1ee-1a8df1b31395', '00000000-0000-4000-a000-0000000000de', 'caceb4e1-bbcb-4cea-9598-bd15dd0d27d4', 'questions', 'Is the document corpus manually curated by a named team and version-controlled (e.g., in SharePoint or a CMS), or does the RAG indexer ingest documents dynamically from a broader shared drive or intranet?', NULL, 'yes manually curated', '00000000-0000-4000-b000-0000000000de', 'answered', '2026-06-10T15:50:42.589714+00:00') ON CONFLICT DO NOTHING;
