INSERT INTO questions ("id", "org_id", "use_case_id", "stage", "text", "assignee", "answer", "answered_by", "status", "created_at") VALUES ('fed3a8bb-8b98-4e45-a87b-1f1be99ee363', '00000000-0000-4000-a000-0000000000de', '5576a726-ad6e-4da7-b9d9-6ca3ff8a030e', 'questions', 'Is there a named business owner or team responsible for this tool''s use — someone who could be held accountable for enforcing usage boundaries and responding to a data incident if sensitive notes were inadvertently submitted?', NULL, 'marketing team', '00000000-0000-4000-b000-0000000000de', 'answered', '2026-06-08T13:47:51.064362+00:00') ON CONFLICT DO NOTHING;
INSERT INTO questions ("id", "org_id", "use_case_id", "stage", "text", "assignee", "answer", "answered_by", "status", "created_at") VALUES ('25724478-d9f7-465f-8b2b-26fcb2198b8e', '00000000-0000-4000-a000-0000000000de', '84c9d8a0-f0da-43ca-8e3a-41c529bfbe9d', 'questions', 'What is the ingestion governance process: who decides which documents are added to or removed from the corpus, is there a review step before a document goes live in the index, and is there a mechanism to urgently de-index a document if it should not have been included?', NULL, 'Privacy and security team', '00000000-0000-4000-b000-0000000000de', 'answered', '2026-06-09T03:16:29.803585+00:00') ON CONFLICT DO NOTHING;
