INSERT INTO questions ("id", "org_id", "use_case_id", "stage", "text", "assignee", "answer", "answered_by", "status", "created_at") VALUES ('dae04198-7428-466d-9927-382e1e9d5cac', '00000000-0000-4000-a000-0000000000de', '84c9d8a0-f0da-43ca-8e3a-41c529bfbe9d', 'questions', 'Is the LLM inference layer hosted internally (e.g., self-hosted model, Azure OpenAI with private endpoint and no training opt-in), or does it route queries and retrieved document chunks to a third-party public API such as OpenAI''s platform?', NULL, 'hosted on OpenAI', '00000000-0000-4000-b000-0000000000de', 'answered', '2026-06-09T03:16:29.803585+00:00') ON CONFLICT DO NOTHING;
INSERT INTO questions ("id", "org_id", "use_case_id", "stage", "text", "assignee", "answer", "answered_by", "status", "created_at") VALUES ('ed2e1f23-5033-4d4d-b7c7-61f0d6754363', '00000000-0000-4000-a000-0000000000de', '84c9d8a0-f0da-43ca-8e3a-41c529bfbe9d', 'questions', 'What document classifications are present in the ingested corpus — specifically, are any documents marked confidential, restricted, HR-only, legal-privileged, or containing personal data (PII/sensitive employee information)?', NULL, 'no classification is there', '00000000-0000-4000-b000-0000000000de', 'answered', '2026-06-09T03:16:29.803585+00:00') ON CONFLICT DO NOTHING;
