INSERT INTO questions ("id", "org_id", "use_case_id", "stage", "text", "assignee", "answer", "answered_by", "status", "created_at") VALUES ('58e678e1-cc5d-4484-9974-bc4e18d0b2e1', '00000000-0000-4000-a000-0000000000de', '84c9d8a0-f0da-43ca-8e3a-41c529bfbe9d', 'questions', 'Is the organization subject to any regulatory frameworks — such as GDPR, HIPAA, ISO 27001, or SOC 2 — that govern how internal employee data or company documents must be handled, and has the legal or compliance team reviewed the assistant''s data flows?', NULL, 'GDPR requirements to meet', '00000000-0000-4000-b000-0000000000de', 'answered', '2026-06-09T03:16:29.803585+00:00') ON CONFLICT DO NOTHING;
