INSERT INTO questions ("id", "org_id", "use_case_id", "stage", "text", "assignee", "answer", "answered_by", "status", "created_at") VALUES ('f5e3a602-092e-43e0-8705-a7000136067c', '00000000-0000-4000-a000-0000000000de', '84c9d8a0-f0da-43ca-8e3a-41c529bfbe9d', 'questions', 'Are employee queries to the bot and the document chunks returned in each retrieval logged in a system that is queryable for audit purposes — and does that log capture the employee identity, the query text, and the specific document sources surfaced?', NULL, 'yes they are required but no controls to vlaidate', '00000000-0000-4000-b000-0000000000de', 'answered', '2026-06-09T03:16:29.803585+00:00') ON CONFLICT DO NOTHING;
