INSERT INTO questions ("id", "org_id", "use_case_id", "stage", "text", "assignee", "answer", "answered_by", "status", "created_at") VALUES ('487420e0-6dad-4714-909b-13385d64bc2b', '00000000-0000-4000-a000-0000000000de', '84c9d8a0-f0da-43ca-8e3a-41c529bfbe9d', 'questions', 'Is there a named product or system owner accountable for the assistant''s accuracy and data boundary controls — and does that person have a defined process for receiving and acting on employee reports of incorrect, hallucinated, or inappropriately surfaced answers?', NULL, 'Engineer team', '00000000-0000-4000-b000-0000000000de', 'answered', '2026-06-09T03:16:29.803585+00:00') ON CONFLICT DO NOTHING;
