INSERT INTO questions ("id", "org_id", "use_case_id", "stage", "text", "assignee", "answer", "answered_by", "status", "created_at") VALUES ('3821394c-3129-4663-99df-75bc18eaeccb', '00000000-0000-4000-a000-0000000000de', '655e2baa-9a21-4e1b-8449-d9f8202770a7', 'questions', 'Which LLM provider and model serves this assistant, and is sensitive HR data — including case notes, health information, and protected characteristics — processed within your organization''s tenant (e.g., Azure OpenAI private deployment) or transmitted to an external public API endpoint?', NULL, NULL, NULL, 'open', '2026-07-04T10:53:14.456206+00:00') ON CONFLICT DO NOTHING;
INSERT INTO questions ("id", "org_id", "use_case_id", "stage", "text", "assignee", "answer", "answered_by", "status", "created_at") VALUES ('4a240df4-5300-4a5c-ba98-b9212f8d7a2c', '00000000-0000-4000-a000-0000000000de', '655e2baa-9a21-4e1b-8449-d9f8202770a7', 'questions', 'Is role-based access filtering enforced at the retrieval layer (i.e., the vector store or document index returns only records the querying user is authorized to see), or is it applied at the prompt or output layer after retrieval has already occurred?', NULL, NULL, NULL, 'open', '2026-07-04T10:53:14.456206+00:00') ON CONFLICT DO NOTHING;
INSERT INTO questions ("id", "org_id", "use_case_id", "stage", "text", "assignee", "answer", "answered_by", "status", "created_at") VALUES ('e308d025-e182-4525-ac90-b385fed9133c', '00000000-0000-4000-a000-0000000000de', '655e2baa-9a21-4e1b-8449-d9f8202770a7', 'questions', 'Is the draft approval requirement — before any AI-generated communication or guidance is used — enforced by a technical workflow gate (e.g., a required human approval step in the platform before the draft can be copied, sent, or saved to the case record), or is it currently governed only by policy and training?', NULL, NULL, NULL, 'open', '2026-07-04T10:53:14.456206+00:00') ON CONFLICT DO NOTHING;
INSERT INTO questions ("id", "org_id", "use_case_id", "stage", "text", "assignee", "answer", "answered_by", "status", "created_at") VALUES ('2ec879f0-b959-402c-9586-03f14f8779b0', '00000000-0000-4000-a000-0000000000de', '655e2baa-9a21-4e1b-8449-d9f8202770a7', 'questions', 'When the assistant surfaces an escalation recommendation for a high-risk scenario (e.g., harassment, retaliation, safety, accommodation), is that recommendation logged and tracked to a documented human disposition (acknowledged, escalated, or overridden with reason), or is it surfaced as a transient suggestion with no closure tracking?', NULL, NULL, NULL, 'open', '2026-07-04T10:53:14.456206+00:00') ON CONFLICT DO NOTHING;
INSERT INTO questions ("id", "org_id", "use_case_id", "stage", "text", "assignee", "answer", "answered_by", "status", "created_at") VALUES ('89ccef2d-50a3-4ef5-a8ee-66802c1c1986', '00000000-0000-4000-a000-0000000000de', '655e2baa-9a21-4e1b-8449-d9f8202770a7', 'questions', 'When the assistant presents recommended next steps or escalation paths, does it also surface the evidence basis and any significant omissions or uncertainties in the retrieved information — for example, flagging if a pending accommodation request exists but relevant details are outside the current retrieval scope?', NULL, NULL, NULL, 'open', '2026-07-04T10:53:14.456206+00:00') ON CONFLICT DO NOTHING;
INSERT INTO questions ("id", "org_id", "use_case_id", "stage", "text", "assignee", "answer", "answered_by", "status", "created_at") VALUES ('792e4239-a5e7-4bff-9120-119e19ca8bd9', '00000000-0000-4000-a000-0000000000de', '655e2baa-9a21-4e1b-8449-d9f8202770a7', 'questions', 'Who is the named system owner and named data owner for this assistant, and do those roles have documented responsibility for reviewing AI output quality, access control changes, and incident response — or is ownership currently informal?', NULL, NULL, NULL, 'open', '2026-07-04T10:53:14.456206+00:00') ON CONFLICT DO NOTHING;
INSERT INTO questions ("id", "org_id", "use_case_id", "stage", "text", "assignee", "answer", "answered_by", "status", "created_at") VALUES ('9bd2fd7c-78d8-494c-8464-3f47a5a968f2', '00000000-0000-4000-a000-0000000000de', '655e2baa-9a21-4e1b-8449-d9f8202770a7', 'questions', 'What is the current deployment timeline and gating criteria for expanding access from HR business partners and employee relations specialists to people managers? Specifically, is there a defined set of access model reviews and guardrail validations that must pass before manager rollout begins?', NULL, NULL, NULL, 'open', '2026-07-04T10:53:14.456206+00:00') ON CONFLICT DO NOTHING;
INSERT INTO questions ("id", "org_id", "use_case_id", "stage", "text", "assignee", "answer", "answered_by", "status", "created_at") VALUES ('2cd913a5-158e-4678-b06e-8ec8cae516cd', '00000000-0000-4000-a000-0000000000de', '655e2baa-9a21-4e1b-8449-d9f8202770a7', 'questions', 'Are all HRIS system connections strictly read-only with no capability to write, update, create, or flag records — including no ability to add notes, update case status, or create tasks — even if that capability exists in the underlying API?', NULL, NULL, NULL, 'open', '2026-07-04T10:53:14.456206+00:00') ON CONFLICT DO NOTHING;
INSERT INTO questions ("id", "org_id", "use_case_id", "stage", "text", "assignee", "answer", "answered_by", "status", "created_at") VALUES ('83088ca1-6732-4a6e-a0d7-77194bbf2c16', '00000000-0000-4000-a000-0000000000de', '655e2baa-9a21-4e1b-8449-d9f8202770a7', 'questions', 'Which regulatory frameworks explicitly govern this deployment — for example, GDPR or state privacy law for employee data, ADA and FMLA for accommodation and leave case handling, EEOC guidance for discrimination and harassment, or sector-specific employment law — and has legal or compliance reviewed the assistant''s output scope against those obligations?', NULL, NULL, NULL, 'open', '2026-07-04T10:53:14.456206+00:00') ON CONFLICT DO NOTHING;
INSERT INTO questions ("id", "org_id", "use_case_id", "stage", "text", "assignee", "answer", "answered_by", "status", "created_at") VALUES ('cb1bd7e9-6623-458b-8f83-50e55c06de1c', '00000000-0000-4000-a000-0000000000de', '655e2baa-9a21-4e1b-8449-d9f8202770a7', 'questions', 'Is there a defined process and technical mechanism for HR users to flag an AI output as incorrect, harmful, or biased — and does that flag route to a documented review process that can trigger prompt updates, retrieval corrections, or retraining?', NULL, NULL, NULL, 'open', '2026-07-04T10:53:14.456206+00:00') ON CONFLICT DO NOTHING;
INSERT INTO questions ("id", "org_id", "use_case_id", "stage", "text", "assignee", "answer", "answered_by", "status", "created_at") VALUES ('aca43126-d5b9-4da7-806c-2176af2225b9', '00000000-0000-4000-a000-0000000000de', '655e2baa-9a21-4e1b-8449-d9f8202770a7', 'questions', 'Are the approved HR policy documents and knowledge articles version-controlled with a defined refresh process, and does the retrieval index reflect only currently authorized policy versions — preventing the assistant from citing superseded policies or outdated benefits guidance?', NULL, NULL, NULL, 'open', '2026-07-04T10:53:14.456206+00:00') ON CONFLICT DO NOTHING;
