GH_TOKEN="${GITHUB_ADMIN_TOKEN:-""}" 

if [[ -z "${GH_TOKEN}" ]]; then
  echo "ERROR: GITHUB_ADMIN_TOKEN env var is not set." >&2
  exit 1
fi

echo "==> Fetching current Copilot policy for org: ${GH_ORG}"
