  -H "Authorization: Bearer ${GH_TOKEN}" \
  -H "Accept: application/vnd.github+json" \
  -H "X-GitHub-Api-Version: 2022-11-28" \
  "https://api.github.com/orgs/${GH_ORG}/copilot/billing" | jq ''.public_code_suggestions''

echo ""
echo "==> MANUAL STEP REQUIRED:"
echo "    Log into GitHub Org Settings > Copilot > Policies and confirm"
echo "    ''Suggestions matching public code'' shows ''Blocked''."
echo "    Then update the OneTrust AI inventory record for the Copilot asset"
echo "    to document this setting as evidence."
