INSERT INTO control_items ("id", "org_id", "use_case_id", "pillar", "control", "why", "requirement", "status", "owner", "created_at", "framework_refs", "stack_implementation", "evidence", "assurance_test", "verification_status", "verification_mode", "verification_note", "verified_by", "verified_at", "artifact_type", "artifact_language", "artifact_filename", "artifact_content", "artifact_generated_at", "capability_id", "evidence_url") VALUES ('cd5ea2f6-3cd7-4830-ad89-0cb09066d626', '00000000-0000-4000-a000-0000000000de', '655e2baa-9a21-4e1b-8449-d9f8202770a7', 2, 'Use separate Entra ID service principals for the RAG indexing pipeline (document ingestion into Azure AI Search) and the user-facing query path, each with least-privilege scoped to their function.', 'A single service account for both ingestion and query means a compromised query-path credential could modify the search index, injecting poisoned policy content or expanding retrieval scope.', 'required', 'gap', NULL, '2026-06-12T05:43:16.455547+00:00', '{"eu_ai_act":"Art. 15 (accuracy, robustness, cybersecurity)","iso_42001":"A.6.2.4; A.8.5","owasp_llm":"LLM06 Excessive Agency; LLM08 Excessive Agency","nist_ai_rmf":"GOVERN 1.7; MANAGE 2.3"}'::jsonb, 'In Entra ID, create two App Registrations: ''HR-Copilot-Indexer'' with Search Index Data Contributor role on the Azure AI Search resource, and ''HR-Copilot-Query'' with Search Index Data Reader role only. Remove any shared keys; use managed identities where possible. Store credentials in Azure Key Vault with separate access policies. The client confirmed separate identities exist — verify the permission boundary matches this specification.', 'Entra ID App Registration export showing two distinct service principals — one with write access to Azure AI Search indexes (indexer) and one with read-only query key access (query) — with no overlapping permissions.', 'Using the query-path service principal credentials, attempt to push a document to the Azure AI Search index; confirm the operation is denied with a 403 Forbidden.', 'not_checked', NULL, NULL, NULL, NULL, 'terraform', 'hcl', 'hr_copilot_search_identities.tf', '# Control: cd5ea2f6-3cd7-4830-ad89-0cb09066d626 — Pillar 2
# Separate Entra ID service principals for RAG indexing vs. query paths (least-privilege).
# SCAFFOLD — review all TODO values before applying. Never apply blindly.

terraform {
  required_providers {
    azurerm = {
      source  = "hashicorp/azurerm"
      version = "~> 3.100"
    }
    azuread = {
      source  = "hashicorp/azuread"
      version = "~> 2.50"
    }
  }
}

provider "azurerm" {
  features {}
  # TODO: set subscription_id to your target Azure subscription
  subscription_id = "<TODO: azure-subscription-id>"
}

provider "azuread" {
  # TODO: set tenant_id to your Entra ID tenant
  tenant_id = "<TODO: entra-tenant-id>"
}

# ---------------------------------------------------------------------------
# Data sources
# ---------------------------------------------------------------------------

data "azurerm_resource_group" "ai_rg" {
  # TODO: replace with the resource group that contains your Azure AI Search resource
  name = "<TODO: ai-resource-group-name>"
}

data "azurerm_search_service" "hr_search" {
  # TODO: replace with your Azure AI Search service name
  name                = "<TODO: azure-ai-search-service-name>"
  resource_group_name = data.azurerm_resource_group.ai_rg.name
}

data "azurerm_key_vault" "hr_kv" {
  # TODO: replace with the Key Vault used to store AI credentials
  name                = "<TODO: key-vault-name>"
  resource_group_name = data.azurerm_resource_group.ai_rg.name
}

# Built-in role definition IDs for Azure AI Search
# Search Index Data Contributor: 8ebe5a00-799e-43f5-93ac-243d3dce84a7
# Search Index Data Reader:      1407120a-92aa-4202-b7e9-c0e197c71c8f
data "azurerm_role_definition" "search_index_contributor" {
  name  = "Search Index Data Contributor"
  scope = data.azurerm_search_service.hr_search.id
}

data "azurerm_role_definition" "search_index_reader" {
  name  = "Search Index Data Reader"
  scope = data.azurerm_search_service.hr_search.id
}

# ---------------------------------------------------------------------------
# App Registration: HR-Copilot-Indexer  (ingestion / write path)
# ---------------------------------------------------------------------------

resource "azuread_application" "hr_copilot_indexer" {
  display_name = "HR-Copilot-Indexer"

  # Restrict to this tenant only — no multi-tenant
  sign_in_audience = "AzureADMyOrg"

  # TODO: add owners (Entra object IDs of team members responsible for this app)
  owners = []
}

resource "azuread_service_principal" "hr_copilot_indexer" {
  client_id = azuread_application.hr_copilot_indexer.client_id
  # Prevent accidental deletion when assigned to roles
  use_existing = false
}

# No client secret — prefer managed identity or federated credential.
# If a secret is strictly required, uncomment and store the value in Key Vault (see below).
# resource "azuread_application_password" "hr_copilot_indexer_secret" {
#   application_id = azuread_application.hr_copilot_indexer.id
#   display_name   = "indexer-secret-rotation-1"
#   end_date       = "<TODO: ISO8601 expiry, e.g. 2025-07-01T00:00:00Z>"
# }

# Assign Search Index Data Contributor to the Indexer SP
resource "azurerm_role_assignment" "indexer_search_contributor" {
  principal_id         = azuread_service_principal.hr_copilot_indexer.object_id
  role_definition_name = "Search Index Data Contributor"
  # Scope to the specific search service — not the whole resource group
  scope                = data.azurerm_search_service.hr_search.id

  # Skip the AAD check delay in CI; remove in production if not needed
  skip_service_principal_aad_check = false
}

# ---------------------------------------------------------------------------
# App Registration: HR-Copilot-Query  (user-facing / read path)
# ---------------------------------------------------------------------------

resource "azuread_application" "hr_copilot_query" {
  display_name     = "HR-Copilot-Query"
  sign_in_audience = "AzureADMyOrg"

  # TODO: add owners (Entra object IDs of team members responsible for this app)
  owners = []
}

resource "azuread_service_principal" "hr_copilot_query" {
  client_id    = azuread_application.hr_copilot_query.client_id
  use_existing = false
}

# Assign Search Index Data Reader ONLY to the Query SP
resource "azurerm_role_assignment" "query_search_reader" {
  principal_id         = azuread_service_principal.hr_copilot_query.object_id
  role_definition_name = "Search Index Data Reader"
  scope                = data.azurerm_search_service.hr_search.id

  skip_service_principal_aad_check = false
}

# ---------------------------------------------------------------------------
# Key Vault access policies — separate secrets per identity
# Prefer Key Vault RBAC (azurerm_role_assignment) if your KV uses RBAC mode.
# ---------------------------------------------------------------------------

# TODO: verify whether your Key Vault uses access policies or RBAC mode.
# The block below uses access policies. If RBAC mode is enabled, replace with
# azurerm_role_assignment using "Key Vault Secrets User" / "Key Vault Secrets Officer".

resource "azurerm_key_vault_access_policy" "indexer_kv_policy" {
  key_vault_id = data.azurerm_key_vault.hr_kv.id
  tenant_id    = data.azurerm_key_vault.hr_kv.tenant_id
  object_id    = azuread_service_principal.hr_copilot_indexer.object_id

  secret_permissions = [
    "Get",    # read its own credential at runtime
    "List",   # enumerate secret versions for rotation
  ]
  # No key or certificate permissions — not needed for this workload
}

resource "azurerm_key_vault_access_policy" "query_kv_policy" {
  key_vault_id = data.azurerm_key_vault.hr_kv.id
  tenant_id    = data.azurerm_key_vault.hr_kv.tenant_id
  object_id    = azuread_service_principal.hr_copilot_query.object_id

  secret_permissions = [
    "Get",
    "List",
  ]
}

# ---------------------------------------------------------------------------
# EXPLICIT DENIAL: remove any Search Service shared/admin keys
# Azure AI Search admin keys grant full read+write+management access.
# Disable them via the az CLI after apply (no Terraform resource exists today):
#
#   az search admin-key renew \
#     --resource-group <TODO: ai-resource-group-name> \
#     --service-name   <TODO: azure-ai-search-service-name> \
#     --key-kind primary    # rotate to invalidate; then disable API-key auth below
#
#   az search service update \
#     --resource-group <TODO: ai-resource-group-name> \
#     --name           <TODO: azure-ai-search-service-name> \
#     --disable-local-auth true          # requires API version 2021-04-01-preview+
# ---------------------------------------------------------------------------

# ---------------------------------------------------------------------------
# Outputs — surface client IDs for downstream pipeline configuration
# ---------------------------------------------------------------------------

output "indexer_client_id" {
  description = "Entra App client ID for the RAG indexing pipeline"
  value       = azuread_application.hr_copilot_indexer.client_id
  sensitive   = false
}

output "query_client_id" {
  description = "Entra App client ID for the user-facing query path"
  value       = azuread_application.hr_copilot_query.client_id
  sensitive   = false
}

output "indexer_sp_object_id" {
  description = "Object ID of the Indexer service principal (for downstream RBAC)"
  value       = azuread_service_principal.hr_copilot_indexer.object_id
}

output "query_sp_object_id" {
  description = "Object ID of the Query service principal (for downstream RBAC)"
  value       = azuread_service_principal.hr_copilot_query.object_id
}
