INSERT INTO control_items ("id", "org_id", "use_case_id", "pillar", "control", "why", "requirement", "status", "owner", "created_at", "framework_refs", "stack_implementation", "evidence", "assurance_test", "verification_status", "verification_mode", "verification_note", "verified_by", "verified_at", "artifact_type", "artifact_language", "artifact_filename", "artifact_content", "artifact_generated_at", "capability_id", "evidence_url") VALUES ('5b6c136b-6a7e-4be7-9c5d-42ece1769220', '00000000-0000-4000-a000-0000000000de', '97cd8230-e2e2-47e4-944a-e5896b5ef796', 5, 'Classify AI output severity levels (Critical, High, Medium, Low, Informational) using defined criteria mapped to contract value thresholds, regulatory exposure, and clause type — and validate that every output includes a severity classification before it is displayed to reviewers.', 'The system determines which contracts are prioritized for review; without consistent, criteria-based severity classification, risk prioritization is opaque and unauditable, and high-risk items may be deprioritized.', 'required', 'gap', NULL, '2026-06-10T03:46:26.461699+00:00', '{"eu_ai_act":"Art. 14 (human oversight); Art. 13 (transparency)","iso_42001":"A.8.3; A.8.4","owasp_llm":"LLM09 Overreliance","nist_ai_rmf":"MEASURE 2.1; MANAGE 1.3"}'::jsonb, 'Document severity classification criteria in the AI inventory Confluence page. In the LLM system prompt, include the severity criteria as a classification rubric. In the application output parser, enforce that every flag object contains a ''risk_severity'' field with a value from the allowed enum [Critical, High, Medium, Low, Informational]; reject and re-prompt if missing. Store the severity criteria version alongside each flag in the database for auditability.', 'Documented severity classification criteria (e.g., Critical = financial exposure >$X or regulatory filing clause missing; Low = minor formatting deviation) and application-layer validation rule rejecting outputs that lack a severity field.', 'Submit 10 test contracts spanning different risk profiles; verify every flag includes a severity classification and that the classification aligns with the documented criteria — confirm a missing-disclosure on a >$1M contract is not classified below High.', 'not_checked', NULL, NULL, NULL, NULL, 'terraform', 'hcl', 'ai_output_validation_schema.tf', '# Control 5b6c136b-6a7e-4be7-9c5d-42ece1769220: Classify AI output severity levels
# Scaffold: DynamoDB schema and Lambda validation function for severity enforcement
# REVIEW BEFORE APPLY: Replace TODO placeholders with your AWS account, region, and function names

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"  # TODO: set to your primary region
}

# DynamoDB table to store AI outputs with severity classifications and audit metadata
resource "aws_dynamodb_table" "ai_output_flags" {
  name           = "ai-contract-review-flags"  # TODO: align naming with your organization''s standards
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "contract_id"
  range_key      = "flag_id"

  attribute {
    name = "contract_id"
    type = "S"
  }

  attribute {
    name = "flag_id"
    type = "S"
  }

  # GSI for querying by severity (enables priority-based review workflows)
  global_secondary_index {
    name            = "risk_severity-index"
    hash_key        = "risk_severity"
    range_key       = "created_at"
    projection_type = "ALL"
  }

  attribute {
    name = "risk_severity"
    type = "S"
  }

  attribute {
    name = "created_at"
    type = "N"
  }

  # TTL for audit log retention (TODO: adjust to your compliance retention policy)
  ttl {
    attribute_name = "ttl"
    enabled        = true
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.dynamodb_key.arn
  }

  point_in_time_recovery {
    enabled = true  # Enable recovery for audit trails
  }

  tags = {
    Environment = "production"  # TODO: update environment tag
    Control     = "5b6c136b-6a7e-4be7-9c5d-42ece1769220"
    Purpose     = "AI output severity classification"
  }
}

# KMS key for DynamoDB encryption
resource "aws_kms_key" "dynamodb_key" {
  description             = "KMS key for AI output flags table encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  tags = {
    Control = "5b6c136b-6a7e-4be7-9c5d-42ece1769220"
  }
}

resource "aws_kms_alias" "dynamodb_key_alias" {
  name          = "alias/ai-output-flags"
  target_key_id = aws_kms_key.dynamodb_key.key_id
}

# IAM role for Lambda validation function
resource "aws_iam_role" "lambda_validation_role" {
  name = "ai-output-severity-validator-role"  # TODO: align with your naming policy

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

# Policy: minimal permissions for Lambda to validate and store flags
resource "aws_iam_role_policy" "lambda_dynamodb_policy" {
  name = "ai-severity-validator-dynamodb"
  role = aws_iam_role.lambda_validation_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "DynamoDBWrite"
        Effect = "Allow"
        Action = [
          "dynamodb:PutItem",
          "dynamodb:UpdateItem"
        ]
        Resource = aws_dynamodb_table.ai_output_flags.arn
      },
      {
        Sid    = "KMSEncrypt"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = aws_kms_key.dynamodb_key.arn
      },
      {
        Sid    = "CloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "arn:aws:logs:*:*:*"  # TODO: constrain to specific log group
      }
    ]
  })
}

# Lambda execution role attachment for basic policies
resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  role       = aws_iam_role.lambda_validation_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

# CloudWatch Log Group for audit trail
resource "aws_cloudwatch_log_group" "severity_validation_logs" {
  name              = "/aws/lambda/ai-output-severity-validator"  # TODO: align with your logging standards
  retention_in_days = 90  # TODO: set per your compliance/audit retention policy

  kms_key_id = aws_kms_key.dynamodb_key.arn

  tags = {
    Control = "5b6c136b-6a7e-4be7-9c5d-42ece1769220"
  }
}

# Output the DynamoDB table name and ARN for application configuration
output "flags_table_name" {
  value       = aws_dynamodb_table.ai_output_flags.name
  description = "DynamoDB table name for storing AI output flags with severity"
}

output "flags_table_arn" {
  value       = aws_dynamodb_table.ai_output_flags.arn
  description = "DynamoDB table ARN for severity-classified AI outputs"
}

output "lambda_role_arn" {
  value       = aws_iam_role.lambda_validation_role.arn
  description = "IAM role ARN for Lambda validation function"
}
