INSERT INTO control_items ("id", "org_id", "use_case_id", "pillar", "control", "why", "requirement", "status", "owner", "created_at", "framework_refs", "stack_implementation", "evidence", "assurance_test", "verification_status", "verification_mode", "verification_note", "verified_by", "verified_at", "artifact_type", "artifact_language", "artifact_filename", "artifact_content", "artifact_generated_at", "capability_id", "evidence_url") VALUES ('cc1274b4-d0e2-477d-8b92-12b06365f2d5', '00000000-0000-4000-a000-0000000000de', '655e2baa-9a21-4e1b-8449-d9f8202770a7', 5, 'Apply output validation rules that detect and flag high-risk content patterns in AI-generated drafts — including termination recommendations, discrimination-adjacent language, legal conclusions, accommodation denials, and references to protected characteristics — before the draft is presented to the user.', 'The top risk is that subtly biased or legally deficient drafts are adopted without meaningful review; automated flagging of high-risk patterns provides a second line of defense before the human review step.', 'required', 'gap', NULL, '2026-06-12T05:43:16.455547+00:00', '{"eu_ai_act":"Art. 14 (human oversight); Art. 9 (risk management)","iso_42001":"A.6.2.6; A.8.3","owasp_llm":"LLM02 Insecure Output Handling","nist_ai_rmf":"MEASURE 2.5; MANAGE 2.2"}'::jsonb, 'Configure Azure OpenAI content filtering custom categories (if available) or implement a post-processing validation step in the application layer that applies regex and keyword detection for high-risk patterns: termination language, accommodation denial, references to health/disability/pregnancy/race/religion, legal conclusions (''you are required by law'', ''this violates''), and performance rating language. When triggered, insert a visible warning banner in the UI: ''This draft contains high-risk content. Additional review by [ER specialist / Legal] is recommended before use.'' Log all flagged outputs with the triggering pattern.', 'Application code or Azure OpenAI content filter configuration showing defined output classification rules for high-risk HR content patterns, with UI flagging behavior when triggered.', 'Generate a draft response that contains a termination recommendation and discrimination-adjacent language; confirm the output is flagged in the UI with a specific warning before the user can proceed to the approval step.', 'not_checked', NULL, NULL, NULL, NULL, 'config', 'json', 'output_validation_highrisk_patterns.json', '// Control: cc1274b4-d0e2-477d-8b92-12b06365f2d5 — Pillar 5: AI Output High-Risk Pattern Validation
// SCAFFOLD — review all pattern lists, thresholds, and integration points before deploying to production.
// Purpose: Defines high-risk content pattern rules for post-processing validation of Azure OpenAI
//          generated drafts in the HR AI application layer. Rules drive UI warning banners and
//          structured log emission. Complement with Azure OpenAI content filter settings (see TODOs).

{
  "$schema": "https://example.org/hr-ai-output-validator/v1",
  "meta": {
    "description": "High-risk pattern ruleset for AI-generated HR draft validation.",
    "version": "1.0.0",
    "owner": "TODO: set owning team — e.g. HR Engineering / ER & Legal",
    "lastReviewed": "TODO: set review date and cadence (recommend quarterly)"
  },

  "azureOpenAIContentFilter": {
    "_comment": "TODO: Configure these settings in Azure OpenAI Studio → your deployment → Content Filters.",
    "_comment2": "Custom categories require Azure OpenAI content filtering (preview). Confirm feature availability for your subscription tier and region.",
    "customBlocklistEnabled": true,
    "customBlocklistId": "TODO: create and reference a custom blocklist resource ID from Azure OpenAI Studio",
    "builtInFilters": {
      "hate": { "severityThreshold": "low", "action": "block" },
      "selfHarm": { "severityThreshold": "low", "action": "block" },
      "sexual": { "severityThreshold": "low", "action": "block" },
      "violence": { "severityThreshold": "low", "action": "block" }
    }
  },

  "postProcessingValidation": {
    "_comment": "These rules are applied in the application layer AFTER receiving the model response and BEFORE rendering it to the user.",
    "_comment2": "Implement the matching engine in your API middleware (e.g. an Azure Function or App Service module). All matches must be logged to your SIEM (Sentinel / Splunk) and displayed as a warning banner.",

    "warningBannerTemplate": "⚠️ This draft contains high-risk content ({CATEGORY}: ''{MATCHED_PHRASE}''). Additional review by {REVIEWER_ROLE} is recommended before use.",

    "reviewerRoleMapping": {
      "_comment": "TODO: confirm correct reviewer roles with HR leadership and Legal.",
      "TERMINATION": "Employee Relations Specialist and Legal Counsel",
      "ACCOMMODATION_DENIAL": "ADA Coordinator and Legal Counsel",
      "PROTECTED_CHARACTERISTIC": "Employee Relations Specialist and Legal Counsel",
      "LEGAL_CONCLUSION": "Legal Counsel",
      "PERFORMANCE_RATING": "HR Business Partner",
      "DISCIPLINARY_ACTION": "Employee Relations Specialist"
    },

    "rules": [
      {
        "id": "TERM-001",
        "category": "TERMINATION",
        "description": "Termination recommendations or language",
        "severity": "HIGH",
        "action": "warn_and_log",
        "matchMode": "regex_case_insensitive",
        "patterns": [
          "\\bterminate[sd]?\\b",
          "\\btermination\\b",
          "\\bdismiss(al|ed)?\\b",
          "\\bdischarge[sd]?\\b",
          "\\blet\\s+(him|her|them|you)\\s+go\\b",
          "\\bend(ing)?\\s+(his|her|their|your|the)?\\s*employment\\b",
          "\\bseparation\\s+from\\s+(employment|service)\\b",
          "\\binvoluntar(y|ily)\\s+(separation|termination|departure)\\b",
          "\\bshould\\s+(be\s+)?fired\\b",
          "\\brecommend(ing|s|ed)?\\s+(immediate\s+)?termination\\b"
        ]
      },
      {
        "id": "ACCOM-001",
        "category": "ACCOMMODATION_DENIAL",
        "description": "Accommodation denial or discouragement language",
        "severity": "HIGH",
        "action": "warn_and_log",
        "matchMode": "regex_case_insensitive",
        "patterns": [
          "\\bdeny(ing)?\\s+(the\s+)?accommodation\\b",
          "\\bden(y|ied|ying)\\s+(reasonable\s+)?accommodation\\b",
          "\\baccommodation\\s+(is\s+)?(not\s+)?(approved|granted|available|feasible|possible|warranted)\\b",
          "\\bundue\\s+hardship\\b",
          "\\bcannot\\s+(provide|grant|offer)\\s+(a\s+|the\s+|any\s+)?accommodation\\b",
          "\\bno\s+accommodation\\s+will\\s+be\\b",
          "\\brequest\\s+(has\s+been\s+|is\s+)?denied\\b"
        ]
      },
      {
        "id": "PROT-001",
        "category": "PROTECTED_CHARACTERISTIC",
        "description": "References to protected characteristics (health, disability, pregnancy, race, religion, age, sex, national origin)",
        "severity": "HIGH",
        "action": "warn_and_log",
        "matchMode": "regex_case_insensitive",
        "_comment": "TODO: Legal review required — some legitimate HR contexts mention these terms. Tune patterns to reduce false positives (e.g. exclude policy citation contexts).",
        "patterns": [
          "\\bdisabilit(y|ies)\\b",
          "\\bmedical\s+(condition|leave|restriction|history)\\b",
          "\\bpregnant\\b",
          "\\bpregnancy\\b",
          "\\bmaternity\\b",
          "\\brace\\b",
          "\\bethnic(ity)?\\b",
          "\\bnational\s+origin\\b",
          "\\breligion\\b",
          "\\breligious\s+(belief|practice|observance|accommodation)\\b",
          "\\bage\\s+(discrimination|bias|factor)\\b",
          "\\bsexual\s+orientation\\b",
          "\\bgender\s+(identity|expression)\\b",
          "\\bmentalhealth\\b",
          "\\bmental\s+health\\b",
          "\\bchronic\s+(illness|condition)\\b"
        ]
