INSERT INTO control_items ("id", "org_id", "use_case_id", "pillar", "control", "why", "requirement", "status", "owner", "created_at", "framework_refs", "stack_implementation", "evidence", "assurance_test", "verification_status", "verification_mode", "verification_note", "verified_by", "verified_at", "artifact_type", "artifact_language", "artifact_filename", "artifact_content", "artifact_generated_at", "capability_id", "evidence_url") VALUES ('a1df79a1-e9f9-4e98-b90e-b9cb16318755', '00000000-0000-4000-a000-0000000000de', '97cd8230-e2e2-47e4-944a-e5896b5ef796', 7, 'Log all legal reviewer corrections — both false positive dismissals and false negative additions — in structured, queryable format with the reviewer identity, timestamp, original AI output, and correction rationale, and review correction trends quarterly to identify systematic AI weaknesses.', 'The client confirmed reviewers can correct flags, but without structured logging and trend analysis, the organization cannot detect whether the AI is systematically missing a class of risk or over-flagging, and audit evidence is incomplete.', 'required', 'gap', NULL, '2026-06-10T03:46:26.461699+00:00', '{"eu_ai_act":"Art. 12 (record-keeping); Art. 14 (human oversight); Art. 9 (risk management)","iso_42001":"A.8.3; A.8.4; A.9.3","owasp_llm":"LLM09 Overreliance","nist_ai_rmf":"MEASURE 2.2; MANAGE 1.3; GOVERN 1.5"}'::jsonb, 'In the application database, create a ''flag_corrections'' table with columns: correction_id, contract_id, flag_id, correction_type ENUM(''false_positive'',''false_negative''), reviewer_id (Okta user ID), timestamp, original_ai_output (JSON), corrected_assessment, correction_rationale. Forward correction events to Splunk via the application''s logging pipeline. Create a Splunk saved search: ''AI Flag Corrections by Type and Clause Category — Last 90 Days'' and add it to the AI monitoring dashboard. Create a quarterly Jira ticket for the rule set owner to review correction trends.', 'Database schema or log format showing structured correction records with fields: contract_id, flag_id, correction_type (false_positive/false_negative), reviewer_id, timestamp, original_ai_output, correction_rationale; quarterly trend report.', 'Query the corrections database for the last quarter; confirm records are structured (not free-text only); verify a trend report was produced and reviewed by the rule set owner.', 'not_checked', NULL, NULL, NULL, NULL, 'terraform', 'hcl', 'flag_corrections_table.tf', '# Control a1df79a1-e9f9-4e98-b90e-b9cb16318755: Log legal reviewer corrections with structured logging for trend analysis
# Scaffold to review and adapt to your database infrastructure before apply

# RDS PostgreSQL table for flag corrections logging
# This resource assumes an existing RDS instance; adjust the db_instance_identifier and subnet group

resource "aws_db_instance" "legal_review_db" {
  # TODO: Replace with your existing RDS instance identifier if already provisioned
  # This example is for reference; if you have an existing database, skip this resource
  # and apply the schema migration separately via your database management tool.
  identifier           = "legal-review-db"
  allocated_storage    = 20
  storage_type         = "gp3"
  engine               = "postgres"
  engine_version       = "15.2"
  instance_class       = "db.t3.micro"
  db_name              = "legal_ai"
  username             = "postgres"
  password             = random_password.db_password.result
  skip_final_snapshot  = false # TODO: Set to true only for dev; production should snapshot
  publicly_accessible  = false
  # TODO: Set your VPC and subnet group
  db_subnet_group_name = "TODO_your_db_subnet_group_name"
  
  tags = {
    Name        = "legal-ai-review-db"
    Pillar      = "7"
    Control     = "a1df79a1-e9f9-4e98-b90e-b9cb16318755"
  }
}

resource "random_password" "db_password" {
  length  = 32
  special = true
}

resource "aws_secretsmanager_secret" "db_password" {
  name                    = "legal-ai-db-password"
  recovery_window_in_days = 7
  
  tags = {
    Control = "a1df79a1-e9f9-4e98-b90e-b9cb16318755"
  }
}

resource "aws_secretsmanager_secret_version" "db_password" {
  secret_id     = aws_secretsmanager_secret.db_password.id
  secret_string = random_password.db_password.result
}

# IAM role for application to read/write corrections table
resource "aws_iam_role" "legal_ai_app_role" {
  name = "legal-ai-app-corrections-writer"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          # TODO: Replace with your application''s compute principal (EC2 instance role, ECS task role, Lambda execution role, etc.)
          AWS = "TODO_your_app_iam_role_arn"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Control = "a1df79a1-e9f9-4e98-b90e-b9cb16318755"
  }
}

# Policy to read the database password from Secrets Manager
resource "aws_iam_role_policy" "legal_ai_db_secret" {
  name = "legal-ai-db-secret-reader"
  role = aws_iam_role.legal_ai_app_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue"
        ]
        Resource = aws_secretsmanager_secret.db_password.arn
      }
    ]
  })
}

# Policy to allow RDS database access (network/database-level)
# NOTE: Actual database user permissions must be set via PostgreSQL GRANT statements
resource "aws_iam_role_policy" "legal_ai_db_access" {
  name = "legal-ai-db-access"
  role = aws_iam_role.legal_ai_app_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "rds-db:connect"
        ]
        # TODO: Update with your RDS instance resource name (ARN format)
        Resource = "arn:aws:rds:TODO_region:TODO_account_id:db:legal-ai-review-db"
      }
    ]
  })
}

# CloudWatch Log Group for application logs (corrections will be sent via app logging pipeline)
resource "aws_cloudwatch_log_group" "legal_ai_corrections" {
  name              = "/aws/legal-ai/flag-corrections"
  retention_in_days = 90

  tags = {
    Control = "a1df79a1-e9f9-4e98-b90e-b9cb16318755"
  }
}

# IAM role for Splunk to ingest CloudWatch Logs
resource "aws_iam_role" "splunk_ingest_role" {
  name = "splunk-legal-ai-ingest"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          # TODO: Replace with Splunk''s AWS account ID if using Splunk Cloud
          # For Splunk Enterprise on-premises, use your EC2 instance role or appropriate service principal
          AWS = "TODO_splunk_account_id_or_service_role"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Control = "a1df79a1-e9f9-4e98-b90e-b9cb16318755"
  }
}

# Policy for Splunk to read CloudWatch Logs
resource "aws_iam_role_policy" "splunk_cloudwatch_logs" {
  name = "splunk-cloudwatch-logs-read"
  role = aws_iam_role.splunk_ingest_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams",
          "logs:GetLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.legal_ai_corrections.arn}:*"
      }
    ]
  })
}

# Metric alarm to alert on high correction volume (potential systematic issue)
resource "aws_cloudwatch_metric_alarm" "high_corrections" {
  alarm_name          = "legal-ai-high-correction-rate"
  comparison_operator = "GreaterThanThreshold"
  evaluation_periods  = "1"
  # TODO: Adjust metric_name and threshold based on your application''s logging format
  # Common approach: count log events matching pattern in CloudWatch Log Group
  metric_name = "CorrectionCount"
  namespace   = "LegalAI"
  period      = "86400" # 1 day
  statistic   = "Sum"
  threshold   = "50" # TODO: Set based on your baseline; this is a placeholder
  alarm_description = "Alert when flag corrections exceed expected daily rate"
  alarm_actions      = ["TODO_sns_topic_arn_for_alerts"]

  tags = {
    Control = "a1df79a1-e9f9-4e98-b90e-b9cb16318755"
  }
}

output "db_endpoint" {
  value = aws_db_instance.legal_review_db.endpoint
  description = "RDS endpoint for flag_corrections table; TODO: Use this in your application connection string"
}

output "cloudwatch_log_group" {
  value = aws_cloudwatch_log_group.legal_ai_corrections.name
  description = "CloudWatch Log Group for forwarding corrections to Splunk"
}
