INSERT INTO control_items ("id", "org_id", "use_case_id", "pillar", "control", "why", "requirement", "status", "owner", "created_at", "framework_refs", "stack_implementation", "evidence", "assurance_test", "verification_status", "verification_mode", "verification_note", "verified_by", "verified_at", "artifact_type", "artifact_language", "artifact_filename", "artifact_content", "artifact_generated_at", "capability_id", "evidence_url") VALUES ('c2855d3a-c5f0-464e-a6a4-3b5fcfb66862', '00000000-0000-4000-a000-0000000000de', '655e2baa-9a21-4e1b-8449-d9f8202770a7', 3, 'Enforce a sensitive data denylist that prevents health information, accommodation request details, protected characteristics, grievance investigation findings, compensation data, and legal-privileged content from being ingested into the Azure AI Search index, matching the client''s confirmed out-of-scope designation for sensitive categories.', 'The client stated sensitive categories are not in scope but also confirmed case notes are not pre-filtered before reaching Azure OpenAI — this control gap means sensitive data could reach the model via case notes unless excluded at ingestion.', 'required', 'gap', NULL, '2026-06-12T05:43:16.455547+00:00', '{"eu_ai_act":"Art. 10 (data governance — bias and special category data); Art. 9 (risk management)","iso_42001":"A.7.4; A.8.4","owasp_llm":"LLM06 Excessive Agency; LLM02 Insecure Output Handling","nist_ai_rmf":"MAP 5.1; MANAGE 2.2"}'::jsonb, 'In Purview Information Protection, create or apply sensitivity labels for ''HR-Health'', ''HR-Accommodation'', ''HR-Protected-Characteristics'', ''HR-Compensation-Restricted'', ''HR-Legal-Privileged'' to source documents in SharePoint Online. In the Azure AI Search indexer skillset, add a custom skill or conditional mapping that checks for these Purview labels and either skips the document or redacts labeled fields before indexing. For Workday HCM, restrict the API query to only the approved fields (role, location, employment type, manager, tenure, case metadata) — do not pull health, accommodation, or compensation fields.', 'Azure AI Search indexer configuration export showing skillset or field mapping rules that exclude documents or fields tagged with sensitive HR categories; Purview Information Protection sensitivity labels applied to source content.', 'Inject a test document containing health accommodation details and protected characteristic references into the source library; verify it is either not indexed or that sensitive fields are redacted before indexing; confirm the content does not appear in query results.', 'not_checked', NULL, NULL, NULL, NULL, 'policy', 'json', 'sensitive_data_denylist_search_indexer.json', '// Control: c2855d3a-c5f0-464e-a6a4-3b5fcfb66862 — Sensitive data denylist for Azure AI Search ingestion
// Pillar 3 | Required — SCAFFOLD: review all TODO markers before applying.
// This artifact contains three coordinated components:
//   1. Purview sensitivity label definitions (ARM/REST payload)
//   2. Azure AI Search indexer skillset with label-filter conditional skill
//   3. Workday HCM API field allowlist reference
// Apply in order; validate in a non-production environment first.

{
  "_comment": "=== COMPONENT 1: Purview Information Protection — Sensitivity Label Definitions ===",
  "_comment_instructions": "POST each label via Microsoft Graph: POST https://graph.microsoft.com/beta/security/informationProtection/sensitivityLabels. Requires InformationProtectionPolicy.ReadWrite.All. Assign to the SharePoint Online site(s) containing HR case notes and documents.",
  "sensitivityLabels": [
    {
      "name": "HR-Health",
      "description": "Documents containing employee health information. Out of scope for AI Search indexing.",
      "color": "#FF0000",
      "tooltip": "Health data — do not index",
      "isActive": true,
      "contentMarkings": [
        {
          "type": "header",
          "text": "RESTRICTED — HR Health Data"
        }
      ],
      "autoLabeling": {
        "enabled": true,
        "conditions": [
          {
            "type": "sensitiveInfoType",
            // TODO: Verify/extend with your jurisdiction-specific health SIT IDs from Purview
            "sensitiveInfoTypeIds": [
              "6f3d4b5c-XXXX-XXXX-XXXX-health-sit-id"
            ]
          }
        ]
      }
    },
    {
      "name": "HR-Accommodation",
      "description": "Documents containing accommodation request details. Out of scope for AI Search indexing.",
      "color": "#FF6600",
      "tooltip": "Accommodation request data — do not index",
      "isActive": true
      // TODO: Add autoLabeling conditions using relevant SITs or keyword dictionaries for accommodation language
    },
    {
      "name": "HR-Protected-Characteristics",
      "description": "Documents referencing protected characteristics (race, religion, sex, disability, etc.). Out of scope for AI Search indexing.",
      "color": "#FF6600",
      "tooltip": "Protected characteristics — do not index",
      "isActive": true
      // TODO: Add autoLabeling conditions; consider trainable classifiers for protected-characteristic language
    },
    {
      "name": "HR-Compensation-Restricted",
      "description": "Documents containing compensation, salary, or bonus data. Out of scope for AI Search indexing.",
      "color": "#FFCC00",
      "tooltip": "Compensation data — do not index",
      "isActive": true,
      "autoLabeling": {
        "enabled": true,
        "conditions": [
          {
            "type": "sensitiveInfoType",
            // TODO: Use built-in ''Salary'' / ''Wage'' SITs or define a custom keyword dictionary
            "sensitiveInfoTypeIds": [
              "compensation-sit-id-XXXX"
            ]
          }
        ]
      }
    },
    {
      "name": "HR-Legal-Privileged",
      "description": "Documents subject to legal professional privilege or under legal hold. Out of scope for AI Search indexing.",
      "color": "#990000",
      "tooltip": "Legal-privileged content — do not index",
      "isActive": true
      // TODO: Coordinate with Legal team; consider manual labeling workflow for attorney-reviewed docs
    }
  ],

  "_comment2": "=== COMPONENT 2: Azure AI Search — Indexer Skillset with Label-Filter Conditional Skill ===",
  "_comment2_instructions": "PUT to: https://<search-service-name>.search.windows.net/skillsets/<skillset-name>?api-version=2023-11-01. Requires Search Service Contributor role. The custom skill calls a thin Azure Function (see TODO) that reads the document''s Purview label via Graph API and returns a block/allow decision.",
  "searchSkillset": {
    "name": "hr-aisearch-skillset",
    // TODO: Replace with your actual Azure AI Search service skillset name
    "description": "HR document skillset with sensitive-label denylist enforcement",
    "cognitiveServices": {
      // TODO: Replace with your Azure AI multi-service account resource ID
      "@odata.type": "#Microsoft.Azure.Search.CognitiveServicesByKey",
      "key": "<TODO: cognitiveServicesKey>"
    },
    "skills": [
      {
        "@odata.type": "#Microsoft.Skills.Custom.WebApiSkill",
        "name": "purview-label-filter",
        "description": "Calls an Azure Function to check Purview sensitivity labels; returns isDenied=true for out-of-scope labels.",
        // TODO: Deploy the Azure Function from the companion repo and insert its URL + key here
        "uri": "https://<TODO: your-function-app>.azurewebsites.net/api/PurviewLabelFilter?code=<TODO: function-key>",
        "httpMethod": "POST",
        "timeout": "PT30S",
        "batchSize": 1,
        "inputs": [
          {
            "name": "documentUrl",
            "source": "/document/metadata_storage_path"
          },
          {
            "name": "documentId",
            "source": "/document/metadata_storage_name"
          }
        ],
        "outputs": [
          {
            "name": "isDenied",
            "targetName": "labelIsDenied"
          },
          {
            "name": "matchedLabel",
            "targetName": "matchedSensitivityLabel"
          }
        ]
      },
      {
        "@odata.type": "#Microsoft.Skills.Util.ConditionalSkill",
        "name": "block-denied-documents",
        "description": "Clears all extractable content for documents flagged by the label filter, preventing indexing of sensitive fields.",
        "inputs": [
          {
            "name": "condition",
            // Condition: only pass content through if NOT denied
            "source": "= $(/document/labelIsDenied) == false"
          },
          {
            "name": "whenTrue",
            "source": "/document/content"
          },
          {
            "name": "whenFalse",
            // Return an empty string; no content reaches downstream skills or the index
            "source": "= ''''"
          }
        ],
        "outputs": [
          {
            "name": "output",
            "targetName": "safeContent"
          }
        ]
      }
      // TODO: Add your remaining extraction/enrichment skills here, sourcing from /document/safeContent
      // e.g. key-phrase extraction, entity recognition — all downstream of the conditional block
    ],
    "indexProjections": {
      "_comment": "Ensure the index field mappings reference /document/safeContent, not /document/content"
    }
  },

  "_comment3": "=== COMPONENT 2a: Azure Function — Purview Label Checker Logic (pseudo-spec) ===",
  "purviewLabelCheckerFunction": {
    "runtime": "dotnet-isolated or node",
    // TODO: Implement this Azure Function; scaffold below describes the required logic
    "logicSpec": [
      "1. Receive documentUrl and documentId from skill input.",
      "2. Call Microsoft Graph: GET /v1.0/sites/{siteId}/drives/{driveId}/items/{itemId}/extractSensitivityLabels",
      "   — requires Sites.Read.All and InformationProtectionPolicy.Read delegated/app permission.",
      "   TODO: Register an App Registration in Entra ID with these Graph scopes; store client secret in Key Vault.",
      "3. Extract the label ''name'' from the response.",
      "4. Compare against the denylist: [''HR-Health'',''HR-Accommodation'',''HR-Protected-Characteristics'',''HR-Compensation-Restricted'',''HR-Legal-Privileged''].",
      "5. Return: { isDenied: true/false, matchedLabel: ''<label name or null>'' }.",
      "6. Log every denied document (documentId + matchedLabel) to a dedicated Log Analytics table for audit."
    ],
    "managedIdentity": "Use system-assigned managed identity for the Function App where possible; avoid storing Graph credentials in app settings."
  },

  "_comment4": "=== COMPONENT 3: Workday HCM — Approved API Field Allowlist ===",
  "_comment4_instructions": "Apply this allowlist in the Workday integration system / API gateway / middleware layer that pulls Workday data for AI Search. Only the fields listed below may be extracted. All others must be explicitly excluded in the integration mapping.",
  "workdayAllowedFields": [
    "Worker_ID",
    "Role_Title",
    "Location",
    "Employment_Type",
    "Manager_Reference",
    "Tenure_Start_Date",
    "Case_Metadata_ID",
    "Case_Status",
    "Case_Category"
  ],
  "workdayDeniedFields": [
    // These fields MUST NOT be queried or mapped in the integration — denylist for reference
    "Health_Conditions",
    "Accommodation_Details",
    "Disability_Status",
    "Protected_Characteristic_Data",
    "Base_Salary",
    "Bonus_Amount",
    "Compensation_Grade",
    "Legal_Hold_Flags",
    "Grievance_Investigation_Notes",
    "Medical_Leave_Details"
    // TODO: Review against your Workday tenant''s exact field/API names (WWS or REST API paths) and update accordingly
  ],
  "workdayIntegrationNote": "TODO: Enforce allowlist in the Workday Studio integration or ISU (Integration System User) permissions. The ISU should be granted GET access only to approved Business Objects/fields. Validate with a Workday architect that no parent object implicitly returns denied child fields."
}
