from __future__ import annotations

from datetime import date
from typing import Literal

from pydantic import BaseModel, Field, validator


class ContractExtraction(BaseModel):
    """Validated output of the GPT-4o contract extraction node."""

    # TODO: Add / remove fields to match your contract schema
    customer_name: str = Field(..., min_length=1, max_length=255)
    sla_tier: Literal["Gold", "Silver", "Bronze"]
    user_count: int = Field(..., ge=1, le=10000)
    contract_start_date: date
    contract_end_date: date
    # TODO: Add additional required fields (e.g., annual_value, renewal_terms)

    @validator("contract_end_date")
    def end_after_start(cls, v: date, values: dict) -> date:  # noqa: N805
        start = values.get("contract_start_date")
        if start and v <= start:
            raise ValueError("contract_end_date must be after contract_start_date")
        return v

    class Config:
        # Reject any extra fields not declared above
        extra = "forbid"
