"""
Control: 69d47a33-57ce-4829-bddd-76b6b6e2733e
LangGraph node: validates GPT-4o extraction output against ContractExtraction schema.
Logs failures to Google Chronicle via Cloud Logging.
SCAFFOLD: wire into your LangGraph StateGraph.
"""
from __future__ import annotations

import json
import logging
import os
from typing import Any

from pydantic import ValidationError

from models.contract_extraction import ContractExtraction

# TODO: Configure structured Cloud Logging handler to forward to Chronicle
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger("contract.validation")

# Chronicle log sink is connected via Cloud Logging → Chronicle forwarding rule.
# TODO: Ensure the GKE workload identity SA has roles/logging.logWriter.


def validation_node(state: dict[str, Any]) -> dict[str, Any]:
    """
    Validates the extraction result stored in state[''extraction_raw''].
    Returns updated state with either:
      - state[''extraction_validated''] = ContractExtraction instance  (success)
      - state[''validation_errors'']    = list of error strings         (failure)
      - state[''next_node''] set accordingly
    """
    raw: dict[str, Any] = state.get("extraction_raw", {})

    try:
        validated = ContractExtraction.model_validate(raw)
        logger.info(
            json.dumps({
                "event": "contract_extraction_validation_success",
                "customer_name": validated.customer_name,
                "sla_tier": validated.sla_tier,
            })
        )
        return {
            **state,
            "extraction_validated": validated.model_dump(),
            "validation_errors": [],
            "next_node": "human_review",
        }

    except ValidationError as exc:
        errors = [str(e) for e in exc.errors()]
        logger.error(
            json.dumps({
                "event": "contract_extraction_validation_failure",
                # TODO: Ensure raw contract text is not logged; log only metadata
                "validation_errors": errors,
                "severity": "ERROR",
            })
        )
        return {
            **state,
            "extraction_validated": None,
            "validation_errors": errors,
            "next_node": "manual_extraction_required",
        }
PYTHON

