"""
Control: 11002c93-f03d-4a3c-a050-6897dffe12b6
LangGraph node: renders welcome_email_template.html with validated parameters only.
Does NOT pass the template through GPT-4o.
SCAFFOLD: wire into your LangGraph StateGraph after the parameter_validation node.
"""
from __future__ import annotations

import logging
import os
from pathlib import Path
from typing import Any

from jinja2 import Environment, FileSystemLoader, select_autoescape, StrictUndefined

logger = logging.getLogger("agent.email_send_node")

# TODO: Set TEMPLATES_DIR to the absolute path of your templates directory
TEMPLATES_DIR = Path(os.environ.get("TEMPLATES_DIR", "TODO-absolute-path/agent/templates"))

# StrictUndefined raises an error if any placeholder is not supplied
_jinja_env = Environment(
    loader=FileSystemLoader(str(TEMPLATES_DIR)),
    autoescape=select_autoescape(["html"]),
    undefined=StrictUndefined,
)

# Allowed placeholder keys — ONLY these may be injected into the template
_ALLOWED_TEMPLATE_VARS = {
    "customer_name",
    "workspace_url",
    "login_url",
    "temporary_password_instructions",
}


def email_send_node(state: dict[str, Any]) -> dict[str, Any]:
    """
    Renders the fixed welcome email template using validated parameters from state.
    Credentials are passed as an Okta activation link, never inline.
    """
    validated: dict[str, Any] = state.get("action_params_validated", {})

    # Only pass explicitly allowed variables to the template
    template_vars: dict[str, Any] = {
        k: v for k, v in validated.items() if k in _ALLOWED_TEMPLATE_VARS
    }

    # Verify all required vars are present before rendering
    missing = _ALLOWED_TEMPLATE_VARS - set(template_vars.keys())
    if missing:
        raise ValueError(f"Missing required template variables: {missing}")

    template = _jinja_env.get_template("welcome_email_template.html")
    rendered_html = template.render(**template_vars)

    logger.info("welcome_email_rendered", extra={"customer_name": template_vars["customer_name"]})

    # TODO: Replace with your actual email-sending integration (e.g., SendGrid, Google Workspace SMTP)
    # send_email(
    #     to=validated["customer_email"],
    #     subject="Welcome to TODO-COMPANY-NAME",
    #     html_body=rendered_html,
    # )

    return {
        **state,
        "email_rendered_html": rendered_html,
        "next_node": "done",
    }
