cat << ''PYTHON_EOF'' > agent/pipeline.py
"""
Scaffold: Onboarding-agent LangGraph pipeline with enforced execution order.
TODO: Review every field name, node implementation, and conditional logic
      before wiring to production integrations.
"""
from langgraph.graph import StateGraph, END
from typing import TypedDict, Optional, List
from enum import IntEnum


class PipelineStage(IntEnum):
    """Monotonically-advancing stage counter — must never regress."""
    INIT               = 0
    SF_READ_DONE       = 1
    HUMAN_APPROVED     = 2
    WORKSPACE_DONE     = 3
    OKTA_DONE          = 4
    EMAIL_DONE         = 5
    JIRA_DONE          = 6
    CALENDAR_DONE      = 7


class AgentState(TypedDict):
    pipeline_stage:   int
    approval_status:  Optional[str]   # ''approved'' | ''rejected''
    okta_user_ids:    Optional[List[str]]
    email_sent:       Optional[bool]
    jira_ticket_id:   Optional[str]
    error:            Optional[str]
    # TODO: add extracted contract fields (customer_name, sla_tier, user_count …)


# ------------------------------------------------------------------
# Guard helper — raises if the state has regressed or skipped a stage
# ------------------------------------------------------------------
def _assert_stage(state: AgentState, required: PipelineStage) -> None:
    if state["pipeline_stage"] != required.value:
        raise ValueError(
            f"Stage violation: expected {required.name} ({required.value}), "
            f"got {state[''pipeline_stage'']}"
        )


# ------------------------------------------------------------------
# Node implementations (stubs — TODO: replace with real logic)
# ------------------------------------------------------------------
def node_salesforce_read(state: AgentState) -> AgentState:
    _assert_stage(state, PipelineStage.INIT)
    # TODO: call Salesforce read integration
    state["pipeline_stage"] = PipelineStage.SF_READ_DONE
    return state


def node_human_approval(state: AgentState) -> AgentState:
    _assert_stage(state, PipelineStage.SF_READ_DONE)
    # TODO: send approval payload to Jira/Slack and block until resolved
    # state["approval_status"] is set by the callback from the reviewer
    return state  # stage advances only via conditional edge below


def node_provision_workspace(state: AgentState) -> AgentState:
    _assert_stage(state, PipelineStage.SF_READ_DONE)  # guard re-checked
    # TODO: call Google Workspace provisioning API
    state["pipeline_stage"] = PipelineStage.WORKSPACE_DONE
    return state


def node_okta_create(state: AgentState) -> AgentState:
    _assert_stage(state, PipelineStage.WORKSPACE_DONE)
    # TODO: call Okta user/group creation API
    state["pipeline_stage"] = PipelineStage.OKTA_DONE
    return state


def node_send_email(state: AgentState) -> AgentState:
    _assert_stage(state, PipelineStage.OKTA_DONE)
    # TODO: send credential/welcome email
    state["pipeline_stage"] = PipelineStage.EMAIL_DONE
    return state


def node_create_jira(state: AgentState) -> AgentState:
    _assert_stage(state, PipelineStage.EMAIL_DONE)
    # TODO: create Jira onboarding ticket
    state["pipeline_stage"] = PipelineStage.JIRA_DONE
    return state


def node_calendar_schedule(state: AgentState) -> AgentState:
    _assert_stage(state, PipelineStage.JIRA_DONE)
    # TODO: schedule Google Calendar onboarding event
    state["pipeline_stage"] = PipelineStage.CALENDAR_DONE
    return state


def node_halt_rejected(state: AgentState) -> AgentState:
    state["error"] = "Pipeline halted: approval rejected or missing."
    return state


# ------------------------------------------------------------------
# Conditional edge functions
# ------------------------------------------------------------------
def after_human_approval(state: AgentState) -> str:
    if state.get("approval_status") == "approved":
        state["pipeline_stage"] = PipelineStage.HUMAN_APPROVED
        return "provision_workspace"
    return "halt_rejected"


def after_okta_create(state: AgentState) -> str:
    if state.get("okta_user_ids"):  # non-empty list required
        return "send_email"
    return "halt_rejected"


def after_send_email(state: AgentState) -> str:
    if state.get("email_sent") is True:
        return "create_jira"
    return "halt_rejected"


# ------------------------------------------------------------------
# Graph assembly
# ------------------------------------------------------------------
def build_graph() -> StateGraph:
    g = StateGraph(AgentState)

    g.add_node("salesforce_read",      node_salesforce_read)
    g.add_node("human_approval",       node_human_approval)
    g.add_node("provision_workspace",  node_provision_workspace)
    g.add_node("okta_create",          node_okta_create)
    g.add_node("send_email",           node_send_email)
    g.add_node("create_jira",          node_create_jira)
    g.add_node("calendar_schedule",    node_calendar_schedule)
    g.add_node("halt_rejected",        node_halt_rejected)

    g.set_entry_point("salesforce_read")

    g.add_edge("salesforce_read", "human_approval")

    g.add_conditional_edges(
        "human_approval",
        after_human_approval,
        {"provision_workspace": "provision_workspace", "halt_rejected": "halt_rejected"}
    )

    g.add_edge("provision_workspace", "okta_create")

    g.add_conditional_edges(
        "okta_create",
        after_okta_create,
        {"send_email": "send_email", "halt_rejected": "halt_rejected"}
    )

    g.add_conditional_edges(
        "send_email",
        after_send_email,
        {"create_jira": "create_jira", "halt_rejected": "halt_rejected"}
    )

    g.add_edge("create_jira",        "calendar_schedule")
    g.add_edge("calendar_schedule",  END)
    g.add_edge("halt_rejected",      END)

    return g

PYPELINE_EOF

