"""
Scaffold: Assert exact edge topology of the onboarding-agent LangGraph.
TODO: Expand with integration-level mocks before running against production.
"""
import pytest
from agent.pipeline import build_graph, PipelineStage


def test_graph_compiles():
    g = build_graph()
    compiled = g.compile()
    assert compiled is not None


def test_required_nodes_present():
    g = build_graph()
    expected_nodes = {
        "salesforce_read", "human_approval", "provision_workspace",
        "okta_create", "send_email", "create_jira", "calendar_schedule", "halt_rejected"
    }
    assert expected_nodes.issubset(set(g.nodes.keys()))


def test_stage_enum_is_monotonic():
    stages = list(PipelineStage)
    for i in range(len(stages) - 1):
        assert stages[i].value < stages[i + 1].value, \
            f"Stage {stages[i].name} does not precede {stages[i+1].name}"

# TODO: add mock-based happy-path and rejection-path end-to-end tests
TEST_EOF

