cat << ''CI_EOF'' > .github/workflows/pipeline_topology_check.yml
name: pipeline-topology-check
on:
  pull_request:
    paths:
      - ''agent/**''
      - ''tests/**''
jobs:
  topology:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-python@v5
        with:
          python-version: ''3.11''   # TODO: pin to your project''s Python version
      - name: Install dependencies
        run: pip install -r requirements.txt  # TODO: ensure langgraph is listed
      - name: Run topology unit tests
        run: pytest tests/test_pipeline_topology.py -v --tb=short
