INSERT INTO control_items ("id", "org_id", "use_case_id", "pillar", "control", "why", "requirement", "status", "owner", "created_at", "framework_refs", "stack_implementation", "evidence", "assurance_test", "verification_status", "verification_mode", "verification_note", "verified_by", "verified_at", "artifact_type", "artifact_language", "artifact_filename", "artifact_content", "artifact_generated_at", "capability_id", "evidence_url") VALUES ('458cf94a-5e05-46a0-801a-e97f9a822f85', '00000000-0000-4000-a000-0000000000de', '159c61b4-30e3-40d4-88f0-f5a4b1d66b1b', 9, 'Log all tool invocations including denied actions (parameter validation failures, blast-radius violations, scope-denied API calls) with the same structured schema as successful actions, and generate real-time alerts for denied actions in Google Chronicle.', 'Denied actions indicate the agent attempted something outside bounds — these are early indicators of misextraction, prompt injection, or drift that require investigation.', 'required', 'gap', NULL, '2026-06-08T11:06:43.005587+00:00', '{"eu_ai_act":"Art. 12 (record-keeping)","iso_42001":"A.6.2.7; A.8.5","owasp_llm":"LLM06 Excessive Agency","nist_ai_rmf":"MEASURE 2.5; MANAGE 3.2"}'::jsonb, 'In LangGraph, wrap each tool invocation in a try/except that logs both success and denial events to Cloud Logging with a severity field (INFO for success, WARNING for denied). Include fields: run_id, tool_name, action_attempted, parameters, denial_reason, timestamp. In Google Chronicle, create YARA-L detection rules matching severity=''WARNING'' AND source=''onboarding-agent'' that trigger alerts to the engineering team''s PagerDuty or Slack channel. Create a Chronicle dashboard ''Onboarding Agent Denied Actions'' for trend monitoring.', 'Google Chronicle detection rules for denied-action log events; sample denied-action log entries showing full context; alert notification configuration.', 'Trigger a parameter validation failure (e.g., invalid Okta group) and confirm a denied-action log entry appears in Google Chronicle within 60 seconds with full context; confirm the engineering team receives an alert.', 'not_checked', NULL, NULL, NULL, NULL, 'detection', 'kql', 'agent_denied_actions_detection.kql', '// Control 458cf94a-5e05-46a0-801a-e97f9a822f85: Pillar 9 | Log all tool invocations including denied actions and alert on denials
// SCAFFOLD — review and adapt Chronicle query fields/syntax and alert routing before deployment

// Data source: Cloud Logging events from LangChain agent with resource.type="cloud_function" or custom application logs
// Event source: severity=''WARNING'' AND source=''onboarding-agent'' AND jsonPayload.event_type=''tool_invocation_denied''

// Chronicle YARA-L detection rule for denied tool invocations
rule agent_tool_invocation_denied_real_time {
  meta:
    name = "Agent Tool Invocation Denied - Real-Time Alert"
    description = "Detects when an AI agent attempt to invoke a tool is denied due to parameter validation, blast-radius, or scope violation."
    severity = "HIGH"
    mitre_attack = "T1110"
    control_ref = "458cf94a-5e05-46a0-801a-e97f9a822f85"

  events:
    $log.severity = "WARNING"
    and $log.source = "onboarding-agent"
    and $log.jsonPayload.event_type = "tool_invocation_denied"
    and $log.timestamp > now() - 1m

  match:
    $log

  outcome:
    // TODO: Configure alert routing in Chronicle UI or API
    // Alert destination: PagerDuty integration (service key: TODO_PAGERDUTY_SERVICE_KEY)
    // Alert destination: Slack webhook (channel: #ai-security, webhook URL: TODO_SLACK_WEBHOOK_URL)
    // Severity: HIGH
    // Include fields in alert: run_id, tool_name, action_attempted, parameters, denial_reason, timestamp
    event_type = "SUSPICIOUS_ACTIVITY"
    severity = "HIGH"
}

// Chronicle YARA-L detection rule for trend analysis - multiple denials from single agent run
rule agent_repeated_denied_invocations_anomaly {
  meta:
    name = "Agent Repeated Denied Tool Invocations - Anomaly Detection"
    description = "Detects multiple denied tool invocations from the same agent run_id within a short time window, indicating potential prompt injection or drift."
    severity = "MEDIUM"
    mitre_attack = "T1110"
    control_ref = "458cf94a-5e05-46a0-801a-e97f9a822f85"

  events:
    $log1.severity = "WARNING"
    and $log1.source = "onboarding-agent"
    and $log1.jsonPayload.event_type = "tool_invocation_denied"
    and $log1.jsonPayload.run_id = $run_id

    $log2.severity = "WARNING"
    and $log2.source = "onboarding-agent"
    and $log2.jsonPayload.event_type = "tool_invocation_denied"
    and $log2.jsonPayload.run_id = $run_id
    and $log2.timestamp > $log1.timestamp
    and $log2.timestamp <= $log1.timestamp + 5m

  match:
    $log1, $log2

  outcome:
    // TODO: Configure alert routing
    // Alert to: Slack channel #ai-security-anomalies
    // Threshold: 3+ denied invocations in 5 minutes from same run_id
    event_type = "ANOMALY_DETECTED"
    severity = "MEDIUM"
}

// Chronicle dashboard definition (configure in Chronicle UI)
