INSERT INTO control_items ("id", "org_id", "use_case_id", "pillar", "control", "why", "requirement", "status", "owner", "created_at", "framework_refs", "stack_implementation", "evidence", "assurance_test", "verification_status", "verification_mode", "verification_note", "verified_by", "verified_at", "artifact_type", "artifact_language", "artifact_filename", "artifact_content", "artifact_generated_at", "capability_id", "evidence_url") VALUES ('203d73b2-7ffb-46cd-bf2d-61f23e58f1f5', '00000000-0000-4000-a000-0000000000de', 'fc90f117-261f-4c81-bfb3-de7f82437c5c', 3, 'Enable GitHub Advanced Security secret scanning on all repositories in the Copilot scope to detect and block hardcoded credentials before they can be surfaced or cross-pollinated by Copilot suggestions.', 'If secrets exist in repos Copilot can read, it may suggest those patterns into other contexts, effectively leaking credentials across team boundaries.', 'required', 'in_place', NULL, '2026-06-08T05:41:45.291508+00:00', '{"eu_ai_act":"Art. 10 (data governance); Art. 15 (accuracy, robustness, cybersecurity)","iso_42001":"A.7.4; A.8.2","owasp_llm":"LLM02 Sensitive Information Disclosure","nist_ai_rmf":"MANAGE 2.2; MANAGE 2.4"}'::jsonb, 'In GitHub Organization Settings > Code security and analysis, enable ''Secret scanning'' and ''Secret scanning push protection'' for all repositories. Review the Security > Secret scanning alerts dashboard weekly. Create a Jira automation rule to generate tickets for any new secret scanning alerts. Remediate all existing findings in IaC and application repos before confirming Copilot scope is clean.', 'GitHub Organization Settings > Code security and analysis showing ''Secret scanning'' and ''Push protection'' enabled for all repositories; alert dashboard showing active scanning with no unresolved critical findings in Copilot-scoped repos.', 'Attempt to push a commit containing a known test secret pattern to a Copilot-scoped repo and confirm push protection blocks it; review the secret scanning alert dashboard for zero unresolved high-severity findings.', 'not_checked', NULL, NULL, NULL, NULL, 'terraform', 'hcl', 'github_advanced_security_secret_scanning.tf', '# Control: 203d73b2-7ffb-46cd-bf2d-61f23e58f1f5 — Enable GHAS secret scanning and push protection on all repos.
# SCAFFOLD — review all TODO values before applying.

terraform {
  required_providers {
    github = {
      source  = "integrations/github"
      version = "~> 6.0"
    }
  }
}

# ---------------------------------------------------------------------------
# Provider configuration
# ---------------------------------------------------------------------------
provider "github" {
  owner = local.github_org
  token = var.github_token  # TODO: source from Secret Manager or environment variable — never hardcode
}

# ---------------------------------------------------------------------------
# Local values — replace all TODOs before applying
# ---------------------------------------------------------------------------
locals {
  github_org = "# TODO: replace with your GitHub Organization name (e.g., my-org)"

  # List of repository names to enable GHAS on.
  # Best practice: manage ALL private repos. Generate this list from:
  #   gh repo list <org> --limit 1000 --json name --jq ''.[].name''
  # TODO: Populate with your actual repo names, or use the data source below
  # to enumerate all repos dynamically (see note on API rate limits).
  target_repos = [
    # "my-app-repo",
    # "terraform-infra",
    # "platform-services",
    # TODO: add all repos in Copilot scope
  ]
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------
variable "github_token" {
  description = "GitHub token with repo admin and security_events scopes."
  type        = string
  sensitive   = true
}

# ---------------------------------------------------------------------------
# Option A: Explicit repo list (recommended for controlled rollout)
# Enable GHAS + secret scanning + push protection per-repo
# ---------------------------------------------------------------------------
resource "github_repository" "ghas_enabled" {
  for_each = toset(local.target_repos)

  name = each.value

  # GHAS must be enabled before secret scanning can be turned on.
  # For GitHub Enterprise Cloud, GHAS is included — confirm your license.
  # TODO: Remove ''security_and_analysis'' block if your plan does not
  #       support GHAS (GitHub Free/Pro) — secret scanning requires GHAS.
  security_and_analysis {
    advanced_security {
      status = "enabled"
    }

    secret_scanning {
      status = "enabled"
    }

    # Push protection blocks commits containing detected secrets.
    # This is the strongest protection — highly recommended.
    secret_scanning_push_protection {
      status = "enabled"
    }
  }

  # IMPORTANT: This resource manages an EXISTING repo.
  # ''lifecycle'' prevents Terraform from accidentally destroying repos.
  lifecycle {
    prevent_destroy = true
    # Only manage the security_and_analysis block; ignore other repo settings
    # that may be managed elsewhere to avoid drift conflicts.
    ignore_changes = [
      description,
      homepage_url,
      topics,
      visibility,
      has_issues,
      has_projects,
      has_wiki,
      allow_merge_commit,
      allow_squash_merge,
      allow_rebase_merge,
      delete_branch_on_merge,
      archived,
    ]
  }
}

# ---------------------------------------------------------------------------
# Option B: Org-level default — enable GHAS on all NEW repos automatically
# This does not retroactively enable on existing repos (use Option A for those).
