import functions_framework
import requests
import json
from datetime import datetime, timedelta
from google.cloud import secretmanager
import os

JIRA_DOMAIN = os.environ.get(''JIRA_DOMAIN'', ''TODO_jira_domain'')
JIRA_API_TOKEN = os.environ.get(''JIRA_API_TOKEN'', ''TODO_jira_api_token'')
CHRONICLE_API_ENDPOINT = os.environ.get(''CHRONICLE_API_ENDPOINT'', ''TODO_chronicle_api_endpoint'')
CHRONICLE_API_KEY = os.environ.get(''CHRONICLE_API_KEY'', ''TODO_chronicle_api_key'')

def get_secret(secret_id):
    """Retrieve secret from GCP Secret Manager"""
    client = secretmanager.SecretManagerServiceClient()
    project_id = os.environ.get(''GCP_PROJECT_ID'')
    name = f"projects/{project_id}/secrets/{secret_id}/versions/latest"
    response = client.access_secret_version(request={"name": name})
    return response.payload.data.decode(''UTF-8'')

@functions_framework.http
def forward_jira_logs(request):
    """Cloud Function: Pull Jira audit logs every 5 min, forward to Chronicle"""
    try:
        # TODO: Use Secret Manager in production
        jira_token = JIRA_API_TOKEN  # get_secret(''jira_api_token'')
        chronicle_key = CHRONICLE_API_KEY  # get_secret(''chronicle_api_key'')
        
        # Query Jira Audit Log API for logs in last 5 minutes
        since = (datetime.utcnow() - timedelta(minutes=5)).isoformat() + ''Z''
        jira_url = f"https://{JIRA_DOMAIN}/rest/api/2/events"
        headers = {
            ''Authorization'': f''Bearer {jira_token}'',
            ''Content-Type'': ''application/json''
        }
        params = {''created'': f''>{since}''}
        
        response = requests.get(jira_url, headers=headers, params=params)
        response.raise_for_status()
        jira_events = response.json().get(''events'', [])
        
        # Transform and forward to Chronicle
        for event in jira_events:
            chronicle_log = {
                ''timestamp'': event.get(''created''),
                ''source_system'': ''jira'',
                ''event_id'': event.get(''id''),
                ''event_type'': event.get(''type''),
                ''user'': event.get(''user'', {}).get(''name''),
                ''action'': event.get(''description''),
                ''resource'': event.get(''association'', {}).get(''key''),
                ''outcome'': ''success''  # TODO: Parse Jira response for actual outcome
            }
            
            # Forward to Chronicle ingestion API
            chronicle_headers = {
                ''Authorization'': f''Bearer {chronicle_key}'',
                ''Content-Type'': ''application/json''
            }
            chronicle_url = f"{CHRONICLE_API_ENDPOINT}/logs:batchCreate"
            requests.post(chronicle_url, json=[chronicle_log], headers=chronicle_headers)
        
        return {''status'': ''ok'', ''logs_forwarded'': len(jira_events)}, 200
    except Exception as e:
        print(f"Error forwarding Jira logs: {str(e)}")
        return {''error'': str(e)}, 500
EOF

