cat > langchain_disclaimer_middleware.py << ''EOF''
"""LangChain output middleware to append disclaimer to all bot responses.

Control ref: 64b5a1e0-5e47-4963-8a2a-65d5d077e4b2
Purpose: Ensure every AI-generated response includes a disclaimer that
answers are summaries and not official policy/legal/HR guidance.
"""

from typing import Any, Dict
from langchain.callbacks.base import BaseCallbackHandler
from langchain.schema import BaseMessage, AIMessage

class DisclaimerMiddleware:
    """Appends a standard disclaimer to LangChain chain outputs."""

    # TODO: Review and customize disclaimer text for your organization
    DISCLAIMER = (
        "\n\n_**⚠️ AI-Generated Summary:**_ This answer is an AI-generated summary "
        "of company documents. It is not official policy, legal, HR, or compliance "
        "guidance. Please verify with the relevant team before acting on this information._"
    )

    @staticmethod
    def add_disclaimer(text: str) -> str:
        """Append disclaimer to response text."""
        if not text:
            return text
        return text.strip() + DisclaimerMiddleware.DISCLAIMER

    @staticmethod
    def process_chain_output(output: Any) -> Any:
        """Process chain output and inject disclaimer.
        
        Args:
            output: The raw output from the LangChain chain (str, dict, or message)
            
        Returns:
            Output with appended disclaimer
        """
        if isinstance(output, str):
            return DisclaimerMiddleware.add_disclaimer(output)
        elif isinstance(output, dict):
            # If output is a dict with a ''text'' or ''output'' key, append to that
            if "text" in output:
                output["text"] = DisclaimerMiddleware.add_disclaimer(output["text"])
            elif "output" in output:
                output["output"] = DisclaimerMiddleware.add_disclaimer(output["output"])
            return output
        elif isinstance(output, BaseMessage):
            # If LangChain message object, create new message with disclaimer
            original_text = output.content if hasattr(output, "content") else str(output)
            new_text = DisclaimerMiddleware.add_disclaimer(original_text)
            return AIMessage(content=new_text)
        else:
            # Fallback: convert to string and append
            return DisclaimerMiddleware.add_disclaimer(str(output))


# ============================================================================
# EXAMPLE INTEGRATION PATTERNS
# ============================================================================

# Pattern 1: Wrap chain.run() or chain.invoke()
# ============================================================================
from langchain.chains import LLMChain  # TODO: adjust import to your chain type

def run_chain_with_disclaimer(chain, **kwargs) -> str:
    """Execute chain and automatically append disclaimer to output."""
    output = chain.invoke(kwargs)  # TODO: replace with .run() if using legacy API
    return DisclaimerMiddleware.process_chain_output(output)


# Pattern 2: Use as a custom callback during chain execution
# ============================================================================
class DisclaimerCallback(BaseCallbackHandler):
    """LangChain callback to capture and modify output."""
    
    def on_chain_end(self, outputs: Dict[str, Any], **kwargs: Any) -> None:
        """Called when chain finishes. Inject disclaimer into outputs."""
        # TODO: Modify outputs dict in-place if chain stores final text
        for key in outputs:
            if isinstance(outputs[key], str):
                outputs[key] = DisclaimerMiddleware.add_disclaimer(outputs[key])


# Pattern 3: Direct integration in your chain construction
# ============================================================================
# Example:
#   chain = (
#       prompt
#       | llm
#       | StrOutputParser()
#       | (lambda x: DisclaimerMiddleware.add_disclaimer(x))
#   )


# ============================================================================
# TESTING
# ============================================================================

if __name__ == "__main__":
    # Simple test of disclaimer injection
    test_response = "HR policy requires 3 weeks vacation approval in advance."
    result = DisclaimerMiddleware.add_disclaimer(test_response)
    print("Original:")
    print(test_response)
    print("\nWith Disclaimer:")
    print(result)
    assert DisclaimerMiddleware.DISCLAIMER in result, "Disclaimer not appended!"
    print("\n✓ Disclaimer middleware test passed.")
EOF

echo "✓ LangChain disclaimer middleware scaffold created: langchain_disclaimer_middleware.py"
echo ""
