"""Datadog logging integration for helpdesk fallback events.

Logs instances where the knowledge base cannot answer a question.
"""

import logging
import json
from datetime import datetime
import requests

# TODO: Retrieve Datadog API key from GCP Secret Manager or environment
DATADOG_API_KEY = "<UNKNOWN>"  # Store securely, never hardcode
DATADOG_ENDPOINT = "<UNKNOWN>"

class DatadogFallbackHandler(logging.Handler):
    """Custom logging handler to send fallback events to Datadog."""
    
    def emit(self, record):
        """Send a log record to Datadog."""
        if not record.tags.get("helpdesk.output.no_source"):
            return
        
        payload = {
            "hostname": "langchain-helpdesk",
            "service": "langchain-qa",
            "tags": ["helpdesk.output.no_source", "retrieval_threshold_miss"],
            "message": record.getMessage(),
            "timestamp": int(datetime.utcnow().timestamp()),
            "level": record.levelname,
            "logger.name": record.name,
        }
        
        headers = {
            "DD-API-KEY": DATADOG_API_KEY,
            "Content-Type": "application/json",
        }
        
        try:
            # TODO: Verify correct Datadog logging endpoint for your region
            response = requests.post(
                f"{DATADOG_ENDPOINT}/v1/input",
                headers=headers,
                json=payload,
                timeout=5,
            )
            response.raise_for_status()
        except requests.RequestException as e:
            logging.error(f"Failed to send fallback event to Datadog: {e}")

def setup_datadog_logging():
    """Configure Datadog handler for fallback events."""
    logger = logging.getLogger("langchain.helpdesk")
    datadog_handler = DatadogFallbackHandler()
    logger.addHandler(datadog_handler)
    return logger

if __name__ == "__main__":
    logger = setup_datadog_logging()
    logger.warning(
        "Test fallback event",
        extra={"tags": {"helpdesk.output.no_source": True}}
    )
EOF

