cat > langchain_input_validator.py << ''EOF''
import os
from typing import Any, Dict
from langchain_core.runnables import RunnablePassthrough, Runnable
from langchain_core.exceptions import InvalidInputError
import logging

# TODO: Replace with your actual Datadog API key from environment variable
DATADOG_API_KEY = os.getenv(''DATADOG_API_KEY'')
DATADOG_API_URL = ''https://api.datadoghq.com/api/v1/events''

# TODO: Adjust MAX_INPUT_LENGTH based on your LLM context window budget.
#       Current setting: 2,000 characters. For GPT-4 with 8K tokens, ~6,000 chars is safer.
MAX_INPUT_LENGTH = 2000

logger = logging.getLogger(__name__)

def validate_input_length(input_data: Dict[str, Any]) -> Dict[str, Any]:
    """
    Validates that user input does not exceed MAX_INPUT_LENGTH.
    Logs rejections to Datadog with tag ''helpdesk.input.too_long''.
    Raises InvalidInputError if input exceeds limit.
    """
    user_input = input_data.get(''input'', '''')
    input_length = len(user_input)

    if input_length > MAX_INPUT_LENGTH:
        # Log rejection to Datadog
        log_input_rejection(input_length)
        
        logger.warning(
            f''Input rejected: {input_length} characters exceeds max {MAX_INPUT_LENGTH}'',
            extra={''tags'': [''helpdesk.input.too_long'']}
        )
        
        raise InvalidInputError(
            f''Your question is too long — please shorten it and try again. ''
            f''(Max {MAX_INPUT_LENGTH} characters, you provided {input_length})''
        )
    
    return input_data

def log_input_rejection(input_length: int) -> None:
    """
    Posts a Datadog event for input rejections.
    TODO: Ensure DATADOG_API_KEY is set in your deployment environment.
    """
    if not DATADOG_API_KEY:
        logger.error(''DATADOG_API_KEY not set; input rejection not logged to Datadog'')
        return
    
    import requests
    
    event_payload = {
        ''title'': ''LangChain Input Validation: Query Too Long'',
        ''text'': f''Input rejected for exceeding {MAX_INPUT_LENGTH} character limit. Length: {input_length}'',
        ''tags'': [''helpdesk.input.too_long'', ''langchain'', ''security''],
        ''alert_type'': ''warning'',
        ''priority'': ''normal''
    }
    
    try:
        requests.post(
            DATADOG_API_URL,
            params={''api_key'': DATADOG_API_KEY},
            json=event_payload,
            timeout=5
        )
    except Exception as e:
        logger.error(f''Failed to log to Datadog: {e}'')

def build_validated_chain(base_chain: Runnable) -> Runnable:
    """
    Wraps a LangChain base_chain with input validation.
    Usage:
        from langchain.chains import LLMChain
        base_chain = LLMChain(llm=my_llm, prompt=my_prompt)
        validated_chain = build_validated_chain(base_chain)
    """
    return (
        RunnablePassthrough.assign() 
        | RunnablePassthrough(lambda x: validate_input_length(x))
        | base_chain
    )

EOF

