import fnmatch
import logging
import yaml
from typing import List, Dict, Any
from datadog import initialize, api
import os

logger = logging.getLogger(__name__)

class DenylistFilter:
    """Pre-ingestion filter for LangChain document pipeline.
    
    Loads denylist patterns from YAML config and rejects documents
    whose source URIs match denylisted categories.
    """
    
    def __init__(self, denylist_config_path: str, datadog_api_key: str, datadog_app_key: str):
        """Initialize denylist and Datadog client.
        
        Args:
            denylist_config_path: Path to ingestion_denylist.yaml
            datadog_api_key: Datadog API key
            datadog_app_key: Datadog APP key
        """
        self.denylist_config_path = denylist_config_path
        self.denylist_rules = self._load_denylist()
        
        # Initialize Datadog
        options = {
            ''api_key'': datadog_api_key,
            ''app_key'': datadog_app_key,
            ''api_version'': ''v1''
        }
        initialize(**options)
        
    def _load_denylist(self) -> Dict[str, Any]:
        """Load denylist configuration from YAML file."""
        with open(self.denylist_config_path, ''r'') as f:
            config = yaml.safe_load(f)
        return config.get(''denylisted_sources'', [])
    
    def check_document(self, document_source_uri: str) -> tuple[bool, str]:
        """Check if document source matches denylist.
        
        Args:
            document_source_uri: Full source URI/path of document
            
        Returns:
            (is_allowed, rejection_reason). is_allowed=False if denylisted.
        """
        for rule in self.denylist_rules:
            category = rule.get(''category'', ''unknown'')
            patterns = rule.get(''patterns'', [])
            description = rule.get(''description'', '''')
            
            for pattern in patterns:
                # Simple glob matching; can upgrade to regex if needed
                if fnmatch.fnmatch(document_source_uri.lower(), pattern.lower()):
                    reason = f"Denylist match: category={category}, pattern={pattern}, description={description}"
                    return False, reason
        
        return True, ""
    
    def filter_documents(self, documents: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        """Filter a list of documents, rejecting denylisted sources.
        
        Args:
            documents: List of document dicts with ''source'' and ''content'' keys
            
        Returns:
            Filtered list of allowed documents
        """
        allowed_documents = []
        
        for doc in documents:
            source_uri = doc.get(''source'', ''unknown'')
            is_allowed, reason = self.check_document(source_uri)
            
            if is_allowed:
                allowed_documents.append(doc)
            else:
                # Log rejection to Datadog with custom metric
                self._log_rejection_to_datadog(source_uri, reason)
                logger.warning(f"Document ingestion blocked: {source_uri} — {reason}")
        
        return allowed_documents
    
    def _log_rejection_to_datadog(self, source_uri: str, rejection_reason: str) -> None:
        """Send rejection event and metric to Datadog.
        
        Args:
            source_uri: Source URI of rejected document
            rejection_reason: Why it was rejected
        """
        try:
            # Send custom metric
            api.Metric.send(
                metric=''helpdesk.ingestion.denylist_block'',
                points=1,
                tags=[
                    ''source_uri:'' + source_uri[:50],  # Truncate for tag
                    ''rejection_category:'' + rejection_reason.split(''category='')[1].split('','')[0]
                    if ''category='' in rejection_reason else ''unknown''
                ]
            )
            
            # Send event for visibility
            api.Event.create(
                title=''Ingestion denylist block'',
                text=f''Source URI: {source_uri}\nReason: {rejection_reason}'',
                tags=[''ingestion'', ''denylist'', ''security'']
            )
            
            logger.info(f"Rejection logged to Datadog for {source_uri}")
        except Exception as e:
            logger.error(f"Failed to log rejection to Datadog: {e}")

PYEOF

echo "[INFO] LangChain denylist filter function saved to /tmp/langchain_denylist_filter.py"
echo "[INFO] TODO: Integrate this filter into your LangChain document loader pipeline."

# === 3. Example LangChain integration (pseudocode) ===
echo "[INFO] Example LangChain pipeline integration:"
cat > /tmp/langchain_pipeline_example.py <<''PYEOF''
# Example: Using DenylistFilter in LangChain document ingestion
# TODO: Adapt to your actual LangChain pipeline architecture

from langchain.document_loaders import DirectoryLoader
from langchain_denylist_filter import DenylistFilter
import os

# Initialize denylist filter
denylist_filter = DenylistFilter(
    denylist_config_path=''config/ingestion_denylist.yaml'',
    datadog_api_key=os.getenv(''DATADOG_API_KEY''),
    datadog_app_key=os.getenv(''DATADOG_APP_KEY'')
)

# Load documents from source
loader = DirectoryLoader(path="/path/to/documents", glob="**/*.md")
raw_documents = loader.load()

# Convert to list of dicts with ''source'' and ''content''
doc_list = [
    {''source'': doc.metadata.get(''source'', ''unknown''), ''content'': doc.page_content}
    for doc in raw_documents
]

# Apply denylist filter
filtered_documents = denylist_filter.filter_documents(doc_list)

print(f"Ingested {len(filtered_documents)} documents (blocked {len(doc_list) - len(filtered_documents)})")

PYEOF

echo "[INFO] Pipeline integration example saved to /tmp/langchain_pipeline_example.py"

# === 4. Create Datadog monitor for denylist blocks ===
echo "[INFO] Setting up Datadog monitor for denylist blocks..."
cat > /tmp/datadog_monitor_config.json <<''EOF''
{
  "name": "[SECURITY] High-risk document ingestion blocked",
  "type": "metric alert",
  "query": "avg(last_5m):avg:helpdesk.ingestion.denylist_block{*} > 0",
  "message": "Alert: {{value}} document(s) blocked by ingestion denylist.\nReview rejected sources immediately.\n@TODO_SLACK_CHANNEL @TODO_SECURITY_TEAM",
  "tags": ["security", "pillar3", "denylist"],
  "options": {
    "thresholds": {
      "critical": 1,
      "critical_recovery": 0
    },
    "notify_no_data": false,
    "require_full_window": true,
    "escalation_message": "Document ingestion denylist blocks detected. Escalating to security team."
  }
}
EOF

echo "[INFO] Datadog monitor configuration:"
cat /tmp/datadog_monitor_config.json

echo ""
echo "=== IMPLEMENTATION CHECKLIST ==="
echo "[ ] 1. Review and customize config/ingestion_denylist.yaml patterns for your environment"
echo "[ ] 2. Commit denylist.yaml to GitHub repo at ${DENYLIST_FILE_PATH}"
echo "[ ] 3. Copy langchain_denylist_filter.py to your LangChain codebase"
echo "[ ] 4. Install Python dependencies: pip install pyyaml datadog"
echo "[ ] 5. Update langchain_pipeline_example.py to match your actual loader/pipeline"
echo "[ ] 6. Set DATADOG_API_KEY and DATADOG_APP_KEY environment variables"
echo "[ ] 7. Create Datadog monitor using API or UI with config from /tmp/datadog_monitor_config.json"
echo "[ ] 8. Test with a document from a denylisted source and verify rejection + Datadog event"
echo "[ ] 9. Configure Datadog notification channels (Slack, PagerDuty, email) for the monitor"
echo "[ ] 10. Document the denylist maintenance process in your runbook"
echo ""
