    Purpose = "Contract Data Retention & Purge"
    Pillar  = "3"
  }
}

# IAM Policy for Lambda: CloudWatch Logs, DynamoDB/RDS access, Secrets Manager.
resource "aws_iam_role_policy" "contract_purge_lambda_policy" {
  name = "contract-data-purge-lambda-policy"
  role = aws_iam_role.contract_purge_lambda_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.contract_purge_logs.arn}:*"
      },
      {
        Sid    = "DynamoDBAccess"
        Effect = "Allow"
        Action = [
          "dynamodb:Scan",
          "dynamodb:DeleteItem"
        ]
        # TODO: Replace with actual DynamoDB table ARN.
        Resource = "arn:aws:dynamodb:${local.aws_region}:${local.aws_account_id}:table/${local.contract_table_name}"
      },
      {
        Sid    = "RDSAccess"
        Effect = "Allow"
        Action = [
          "rds-db:connect"
        ]
        # TODO: If using RDS, add the resource ARN for the database connection.
        Resource = "arn:aws:rds-db:${local.aws_region}:${local.aws_account_id}:dbuser:*/*"
      },
      {
        Sid    = "SecretsManagerAccess"
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue"
        ]
        Resource = local.splunk_hec_token_arn
      }
    ]
  })
}

# Lambda function for contract data purge.
resource "aws_lambda_function" "contract_purge" {
  filename      = "contract_purge_lambda.zip"
  function_name = "contract-data-purge"
  role          = aws_iam_role.contract_purge_lambda_role.arn
  handler       = "index.lambda_handler"
  runtime       = "python3.11"
  timeout       = 300

  environment {
    variables = {
      RETENTION_DAYS              = local.retention_days
      CONTRACT_TABLE_NAME         = local.contract_table_name
      RETENTION_EXPIRY_ATTRIBUTE  = local.retention_expiry_attribute
      SPLUNK_HEC_URL              = local.splunk_hec_url
      SPLUNK_HEC_TOKEN_ARN        = local.splunk_hec_token_arn
      LOG_GROUP_NAME              = aws_cloudwatch_log_group.contract_purge_logs.name
    }
  }

  tags = {
    Purpose = "Contract Data Retention & Purge"
    Pillar  = "3"
  }
}

# EventBridge rule to trigger Lambda weekly (Sunday at 2 AM UTC).
resource "aws_cloudwatch_event_rule" "contract_purge_schedule" {
  name                = "contract-data-purge-weekly"
  description         = "Trigger contract data purge Lambda weekly"
  schedule_expression = "cron(0 2 ? * SUN *)"

  tags = {
    Purpose = "Contract Data Retention & Purge"
    Pillar  = "3"
  }
}

# EventBridge target: Lambda function.
resource "aws_cloudwatch_event_target" "contract_purge_target" {
  rule      = aws_cloudwatch_event_rule.contract_purge_schedule.name
  target_id = "ContractPurgeLambda"
  arn       = aws_lambda_function.contract_purge.arn
}

# Lambda permission for EventBridge.
resource "aws_lambda_permission" "allow_eventbridge" {
  statement_id  = "AllowExecutionFromEventBridge"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.contract_purge.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.contract_purge_schedule.arn
}

# Optional: DynamoDB TTL configuration (alternative to Lambda purge for DynamoDB).
# Uncomment if using DynamoDB and prefer TTL-based expiry.
# resource "aws_dynamodb_ttl" "contract_table_ttl" {
#   name           = local.contract_table_name
#   attribute_name = local.retention_expiry_attribute
#   enabled        = true
# }

output "lambda_function_arn" {
  value       = aws_lambda_function.contract_purge.arn
  description = "ARN of the contract data purge Lambda function"
}

output "log_group_name" {
  value       = aws_cloudwatch_log_group.contract_purge_logs.name
  description = "CloudWatch Log Group for purge audit logs"
}

output "eventbridge_rule_name" {
  value       = aws_cloudwatch_event_rule.contract_purge_schedule.name
  description = "EventBridge rule triggering weekly purge"
}
