      "maxLength": 200
    },
    "reference_rule_id": {
      "type": "string",
      "description": "Unique identifier for the compliance rule or internal policy (e.g., ''POLICY-2024-001'')",
      "minLength": 1,
      "maxLength": 100
    },
    "reference_rule_text": {
      "type": "string",
      "description": "Full text of the compliance rule or policy clause being violated",
      "minLength": 1,
      "maxLength": 5000
    },
    "risk_severity": {
      "type": "string",
      "enum": ["critical", "high", "medium", "low"],
      "description": "Risk severity level"
    },
    "reasoning": {
      "type": "string",
      "description": "Explanation of why the flagged clause violates the reference rule",
      "minLength": 1,
      "maxLength": 2000
    }
  },
