# --- STEP 3: Create a validation wrapper script for application layer
# This script validates Bedrock output against the schema before persistence.
cat > /tmp/validate_bedrock_output.py << ''EOF''
#!/usr/bin/env python3
import json
import sys
from jsonschema import validate, ValidationError

# Load schema
with open(''/tmp/bedrock_output_schema.json'', ''r'') as f:
    schema = json.load(f)

# Read Bedrock response from stdin (or first argument)
if len(sys.argv) > 1:
    bedrock_response = sys.argv[1]
else:
    bedrock_response = sys.stdin.read()

try:
    # Parse JSON response
    response_data = json.loads(bedrock_response)
    
    # If response is an array of flags, validate each
    if isinstance(response_data, list):
        for idx, flag in enumerate(response_data):
            validate(instance=flag, schema=schema)
            print(f"[OK] Flag {idx} validated successfully", file=sys.stderr)
    # If single object
    elif isinstance(response_data, dict):
        if ''flags'' in response_data and isinstance(response_data[''flags''], list):
            for idx, flag in enumerate(response_data[''flags'']):
                validate(instance=flag, schema=schema)
                print(f"[OK] Flag {idx} validated successfully", file=sys.stderr)
        else:
            validate(instance=response_data, schema=schema)
            print("[OK] Response validated successfully", file=sys.stderr)
    else:
        print("[ERROR] Response is not JSON object or array", file=sys.stderr)
        sys.exit(1)
    
    # Output validated response to stdout
    print(json.dumps(response_data, indent=2))
    sys.exit(0)
    
except ValidationError as e:
    print(f"[ERROR] Validation failed: {e.message}", file=sys.stderr)
    print(f"[ERROR] Failed at path: {''.''.join(str(p) for p in e.path)}", file=sys.stderr)
    sys.exit(1)
except json.JSONDecodeError as e:
    print(f"[ERROR] Invalid JSON: {e}", file=sys.stderr)
    sys.exit(1)
EOF

