RESPONSE=$(aws bedrock-runtime invoke-model \
  --model-id "$MODEL_ID" \
  --region "$REGION" \
  --body "$PAYLOAD" \
  --output text \
  --query ''body'' | tr -d ''\0'')

echo "[INFO] Bedrock response received. Validating schema..."

# Extract content from Bedrock response and validate
echo "$RESPONSE" | /tmp/validate_bedrock_output.py
VALIDATION_EXIT=$?

if [ $VALIDATION_EXIT -ne 0 ]; then
  echo "[ERROR] Bedrock output failed schema validation. Rejecting flag."
  exit 1
fi

echo "[OK] All flags validated. Ready for persistence and display to reviewer."
EOF

