SPLUNK_HEC_TOKEN="${SPLUNK_HEC_TOKEN:-# TODO: export SPLUNK_HEC_TOKEN before running}"

# Splunk index for AI compliance metrics
SPLUNK_INDEX="ai_compliance"

# Jira label to track sampling reviews
JIRA_SAMPLE_LABEL="ai-sample-review"

# Sample review ticket due date (days from today)
DUE_DATE_OFFSET_DAYS=7

# ============================================================================
# FUNCTION: Create a Jira ticket for mandatory sample review
# ============================================================================
function create_sample_review_ticket() {
  local contract_id="$1"
  local contract_title="$2"
  local ai_risk_level="$3"
  
  local due_date=$(date -u -d "+${DUE_DATE_OFFSET_DAYS} days" +%Y-%m-%d)
  
  local ticket_summary="[AI-SAMPLE-REVIEW] ${contract_title} (${contract_id})"
  local ticket_description="Mandatory independent legal review of AI-cleared contract.\n\nContract ID: ${contract_id}\nTitle: ${contract_title}\nAI Risk Level: ${ai_risk_level}\nSampling Rate: ${SAMPLING_RATE}%\n\nThis contract was randomly selected for human review as part of the mandatory sampling policy (${SAMPLING_RATE}% of AI-cleared contracts)."
  
  local jira_payload=$(cat <<EOF
{
  "fields": {
    "project": {
      "key": "${JIRA_PROJECT_KEY}"
    },
    "summary": "${ticket_summary}",
    "description": "${ticket_description}",
    "issuetype": {
      "name": "Task"
    },
    "assignee": {
      "name": "${JIRA_LEGAL_ASSIGNEE}"
    },
    "duedate": "${due_date}",
    "labels": [
      "${JIRA_SAMPLE_LABEL}",
      "mandatory-review"
    ],
    "customfield_XXXXX": "${contract_id}"
  }
}
EOF
  )
  
  # TODO: Replace customfield_XXXXX with your actual custom field ID for contract_id
  
  local response=$(curl -s -X POST \
    "${JIRA_HOST}/rest/api/3/issues" \
    -H "Content-Type: application/json" \
    -H "Authorization: Basic $(echo -n "${JIRA_USER_EMAIL}:${JIRA_API_TOKEN}" | base64)" \
    -d "${jira_payload}")
  
  local ticket_key=$(echo "${response}" | grep -o ''"key":"[^"]*"'' | head -1 | cut -d''"'' -f4)
  
  if [ -z "${ticket_key}" ]; then
    echo "ERROR: Failed to create Jira ticket for contract ${contract_id}"
    echo "Response: ${response}"
    return 1
  fi
  
  echo "Created Jira ticket ${ticket_key} for contract ${contract_id}"
  return 0
}

# ============================================================================
# FUNCTION: Send sampling metrics to Splunk
# ============================================================================
function send_to_splunk() {
  local event_type="$1"
  local contract_id="$2"
  local risk_level="$3"
  local ticket_key="$4"
  
  local timestamp=$(date +%s)
  
  local splunk_event=$(cat <<EOF
{
  "event": {
    "type": "${event_type}",
    "contract_id": "${contract_id}",
    "ai_risk_level": "${risk_level}",
    "jira_ticket": "${ticket_key}",
    "sampling_rate": ${SAMPLING_RATE},
    "timestamp": ${timestamp},
    "index": "${SPLUNK_INDEX}"
  },
  "sourcetype": "ai_contract_sampling",
  "source": "contract_review_automation"
}
EOF
  )
  
  local response=$(curl -s -X POST "${SPLUNK_HEC_URL}" \
    -H "Authorization: Splunk ${SPLUNK_HEC_TOKEN}" \
    -H "Content-Type: application/json" \
    -d "${splunk_event}")
  
  # TODO: Add error handling for Splunk HTTP response
  echo "Sent sampling event to Splunk for contract ${contract_id}"
}

