  # These teams should mirror the Entra ID ''Copilot-Licensed-Engineers'' group
  # synced via SCIM. Remove any team that should NOT have Copilot access.
  copilot_authorized_team_slugs = [
    # TODO: replace with real team slugs, e.g.:
    # "backend-engineers",
    # "platform-engineers",
    # "frontend-engineers",
  ]
}

# ---------------------------------------------------------------------------
# Variables
