# ---------------------------------------------------------------------------
data "github_team" "copilot_teams" {
  for_each = toset(local.copilot_authorized_team_slugs)
  slug     = each.value
}

# ---------------------------------------------------------------------------
# GitHub Copilot seat assignment — scoped to authorized teams only
#
# The github_copilot_organization_settings resource controls:
#   - seat_management_setting: "selected_teams" restricts who gets seats
#   - public_code_suggestions:  "block" prevents suggestions matching public code
