resource "github_copilot_seat_assignment" "engineering_teams" {
  for_each = data.github_team.copilot_teams

  # Assigns the named team a Copilot seat allocation within the org.
  team_id = each.value.id

  # TODO: confirm each team corresponds to the SCIM-synced Entra ID group
  # ''Copilot-Licensed-Engineers'' before applying.
}

# ---------------------------------------------------------------------------
