output "copilot_authorized_team_ids" {
  description = "GitHub team IDs granted Copilot access. Verify against Entra ID group membership."
  value       = { for slug, team in data.github_team.copilot_teams : slug => team.id }
}

output "copilot_seat_management_mode" {
  description = "Must be ''selected_teams'' — alert if this changes."
  value       = github_copilot_organization_settings.copilot_access.seat_management_setting
}

