INSERT INTO control_items ("id", "org_id", "use_case_id", "pillar", "control", "why", "requirement", "status", "owner", "created_at", "framework_refs", "stack_implementation", "evidence", "assurance_test", "verification_status", "verification_mode", "verification_note", "verified_by", "verified_at", "artifact_type", "artifact_language", "artifact_filename", "artifact_content", "artifact_generated_at", "capability_id", "evidence_url") VALUES ('8515d9e9-2627-491a-ad15-b2b2d4df3e66', '00000000-0000-4000-a000-0000000000de', '655e2baa-9a21-4e1b-8449-d9f8202770a7', 2, 'Enforce phased access via Entra ID so that only HR business partners and ER specialists can access the copilot; people managers and all other roles must be explicitly denied until a formal change control decision authorizes expansion.', 'The client confirmed phased rollout but has not decided how to enforce it — without a hard identity-layer gate, an admin could provision manager access prematurely, exposing restricted case data before RBAC validation is complete.', 'required', 'gap', NULL, '2026-06-12T05:43:16.455547+00:00', '{"eu_ai_act":"Art. 9 (risk management — access controls); Art. 14 (human oversight — authorized personnel)","iso_42001":"A.6.2.4; A.8.2","owasp_llm":"LLM06 Excessive Agency","nist_ai_rmf":"GOVERN 1.4; MANAGE 1.2"}'::jsonb, 'In Entra ID, create a security group ''HR-Copilot-Authorized-Users'' containing only HR business partner and ER specialist accounts. Register the copilot as an Enterprise Application; set ''User assignment required'' to Yes. Assign only the HR-Copilot-Authorized-Users group. Create a Conditional Access policy scoped to this app requiring group membership and MFA. Document that any group membership change requires a change request approved by the named HR team lead.', 'Entra ID Enterprise Application assignment showing only the HR-BP and ER-Specialist security groups are assigned; no ''All Users'' assignment; Conditional Access policy scoped to the app requiring group membership.', 'Attempt to authenticate to the copilot with a test account that has the People Manager role but is not in the allowed security groups; confirm access is denied at the Entra ID layer before the application is reached.', 'not_checked', NULL, NULL, NULL, NULL, 'terraform', 'hcl', 'entra_copilot_phased_access.tf', '# Control: Pillar 2 — Enforce phased access via Entra ID for HR Copilot (8515d9e9-2627-491a-ad15-b2b2d4df3e66)
# SCAFFOLD — review every TODO before applying. Do NOT apply blindly.

terraform {
  required_providers {
    azuread = {
      source  = "hashicorp/azuread"
      version = "~> 2.47"
    }
  }
}

# ---------------------------------------------------------------------------
# 1. Data sources — look up existing users/principals by UPN
# ---------------------------------------------------------------------------

# TODO: Replace UPNs with the actual HR Business Partner and ER Specialist
#       accounts that are authorised for Phase 1 access.
data "azuread_user" "hr_bp_users" {
  for_each            = toset([
    # "demo@community.example",
    # "demo@community.example",
  ])
  user_principal_name = each.key
}

data "azuread_user" "er_specialist_users" {
  for_each            = toset([
    # "demo@community.example",
    # "demo@community.example",
  ])
  user_principal_name = each.key
}

# ---------------------------------------------------------------------------
# 2. Authorised-users security group
# ---------------------------------------------------------------------------

resource "azuread_group" "hr_copilot_authorized" {
  display_name     = "HR-Copilot-Authorized-Users"
  description      = "Phase-1 gate group: HR Business Partners and ER Specialists only. Membership changes require an approved change request signed off by the named HR team lead."
  security_enabled = true
  mail_enabled     = false

  # Prevent accidental dynamic-membership rules from bypassing the gate
  types = []

  members = concat(
    [for u in data.azuread_user.hr_bp_users : u.id],
    [for u in data.azuread_user.er_specialist_users : u.id]
  )
}

# ---------------------------------------------------------------------------
# 3. Enterprise Application registration for the HR Copilot
# ---------------------------------------------------------------------------

# TODO: If the Copilot is already registered, import it instead of creating.
#       Run: terraform import azuread_application.hr_copilot <existing-application-object-id>
resource "azuread_application" "hr_copilot" {
  display_name = "HR-ER-Copilot"  # TODO: Match the exact display name in your tenant

  # TODO: Set the correct redirect URIs for your Copilot deployment
  web {
    redirect_uris = [
      # "https://<your-copilot-hostname>/auth/callback",
    ]
  }

  # Restrict token issuance to assigned users/groups only (enforced at SP level below)
}

resource "azuread_service_principal" "hr_copilot" {
  client_id = azuread_application.hr_copilot.client_id

  # KEY GATE: User assignment required = true
  # Only members of assigned groups/users can obtain tokens for this app.
  app_role_assignment_required = true

  tags = ["HR", "Copilot", "PhaseOne", "RestrictedAccess"]
}

# ---------------------------------------------------------------------------
# 4. Assign ONLY the authorised group to the Enterprise Application
#    (no direct user assignments — all access flows through the group)
# ---------------------------------------------------------------------------

resource "azuread_app_role_assignment" "hr_copilot_group_assignment" {
  app_role_id         = "00000000-0000-0000-0000-000000000000" # Default role (no custom app role defined)
  principal_object_id = azuread_group.hr_copilot_authorized.id
  resource_object_id  = azuread_service_principal.hr_copilot.object_id
}

# ---------------------------------------------------------------------------
# 5. Conditional Access Policy — enforce group membership + MFA
# ---------------------------------------------------------------------------

# TODO: Confirm the named location / trusted network CIDRs (if any) to exclude.
# TODO: Confirm the CA policy mode: start with "report" before switching to "enabled".
resource "azuread_conditional_access_policy" "hr_copilot_mfa_gate" {
  display_name = "CA-HR-Copilot-GroupMFA-PhaseOne"
  state        = "enabledForReportingButNotEnforced" # TODO: change to "enabled" after validation

  conditions {
    client_app_types = ["browser", "mobileAppsAndDesktopClients"]

    applications {
      included_applications = [azuread_application.hr_copilot.client_id]
    }

    users {
      # Only members of the authorised group are in scope;
      # everyone else is implicitly blocked by app_role_assignment_required = true.
      included_groups = [azuread_group.hr_copilot_authorized.id]

      # TODO: Add break-glass / emergency-access accounts to excluded_users
      excluded_users = [
        # "<break-glass-account-object-id>",
      ]
    }

    # TODO: Restrict to compliant/Entra-joined devices if your policy requires it.
    # devices {
    #   filter {
    #     mode = "include"
    #     rule = "device.isCompliant -eq True"
    #   }
    # }
  }

  grant_controls {
    operator          = "AND"
    built_in_controls = ["mfa"]  # MFA required for every session
  }

  session_controls {
    # TODO: Tune sign-in frequency to match your session policy (e.g. 8 hours)
    sign_in_frequency {
      value         = 8
      type          = "hours"
      is_enabled    = true
      authentication_type = "primaryAndSecondaryAuthentication"
      frequency_interval  = "timeBased"
    }
  }
}

# ---------------------------------------------------------------------------
# 6. Outputs — expose IDs for downstream reference / audit
# ---------------------------------------------------------------------------

output "authorized_group_id" {
  description = "Object ID of HR-Copilot-Authorized-Users group. Reference this in change-control documentation."
  value       = azuread_group.hr_copilot_authorized.id
}

output "copilot_application_client_id" {
  description = "Client (Application) ID of the registered HR Copilot enterprise app."
  value       = azuread_application.hr_copilot.client_id
}

output "conditional_access_policy_id" {
  description = "ID of the Conditional Access policy enforcing group membership + MFA."
  value       = azuread_conditional_access_policy.hr_copilot_mfa_gate.id
}

# ---------------------------------------------------------------------------
# CHANGE-CONTROL NOTE (embed in your runbook / ITSM ticket template):
#
# Any addition to azuread_group.hr_copilot_authorized MUST be accompanied by:
#   1. An approved Change Request in the HR Service Delivery ITSM tool.
#   2. Sign-off from the named HR team lead (document their UPN here: TODO).
#   3. A Terraform plan reviewed by the IAM team before apply.
#   4. An audit log entry in OneTrust GRC referencing this control ref:
