    logger.info("LangChain prompt injection defense configured.")

LANGCHAIN_EOF

echo "✓ LangChain chain configuration with injection defenses created: langchain_chain_config.py"
echo "✓ Before applying, review TODO markers and customize for your environment."
echo ""
