import re
from typing import Dict, Any
from langchain.schema import Document

# TODO: Adjust these patterns based on known injection attacks targeting your use case
INJECTION_PATTERNS = [
    r''ignore\s+previous\s+instructions'',
    r''system\s+override'',
    r''disregard\s+content\s+policy'',
    r''execute\s+command'',
    r''run\s+python'',
    r''eval\('',
    r''execute\s+sql'',
    r''bash\s+command'',
]

# TODO: Set token budget based on max safe contract/calendar size. Default: 2000 tokens
TOKEN_BUDGET = 2000

# TODO: Define what constitutes "suspicious" for flagging (e.g., >3 injection patterns found)
SUSPICIOUS_THRESHOLD = 3

def sanitize_salesforce_contract(raw_content: str) -> Dict[str, Any]:
    """
    Sanitize Salesforce contract text before injection into prompt.
    Returns: {''clean_content'': str, ''is_suspicious'': bool, ''detected_patterns'': list}
    """
    detected_patterns = []
    clean_content = raw_content
    
    # Detect injection patterns
    for pattern in INJECTION_PATTERNS:
        if re.search(pattern, clean_content, re.IGNORECASE):
            detected_patterns.append(pattern)
    
    # Strip suspicious patterns (preserve document integrity note)
    for pattern in INJECTION_PATTERNS:
        clean_content = re.sub(pattern, "[REDACTED]", clean_content, flags=re.IGNORECASE)
    
    # Enforce token budget (rough estimate: 1 token ≈ 4 chars)
    if len(clean_content) > TOKEN_BUDGET * 4:
        clean_content = clean_content[:TOKEN_BUDGET * 4]
        clean_content += "\n[TRUNCATED: Contract exceeded token budget]"
    
    is_suspicious = len(detected_patterns) >= SUSPICIOUS_THRESHOLD
    
    return {
        "clean_content": clean_content,
        "is_suspicious": is_suspicious,
        "detected_patterns": detected_patterns,
        "truncated": len(raw_content) > TOKEN_BUDGET * 4
    }

def sanitize_calendar_event(event_data: Dict[str, Any]) -> Dict[str, Any]:
    """
    Sanitize Google Calendar event data (title, description, location).
    Returns: {''clean_event'': dict, ''is_suspicious'': bool, ''detected_patterns'': list}
    """
    detected_patterns = []
    clean_event = event_data.copy()
    
    for field in [''summary'', ''description'', ''location'']:
        if field not in clean_event or not clean_event[field]:
            continue
        
        field_content = clean_event[field]
        
        # Detect patterns in this field
        for pattern in INJECTION_PATTERNS:
            if re.search(pattern, field_content, re.IGNORECASE):
                detected_patterns.append(f"{field}:{pattern}")
        
        # Strip patterns
        for pattern in INJECTION_PATTERNS:
            clean_event[field] = re.sub(pattern, "[REDACTED]", field_content, flags=re.IGNORECASE)
        
        # Enforce token budget per field
        if len(clean_event[field]) > TOKEN_BUDGET:
            clean_event[field] = clean_event[field][:TOKEN_BUDGET] + "[TRUNCATED]"
    
    is_suspicious = len(detected_patterns) >= SUSPICIOUS_THRESHOLD
    
    return {
        "clean_event": clean_event,
        "is_suspicious": is_suspicious,
        "detected_patterns": detected_patterns
    }
EOF

