        # 2. customfield_approval_confirmation checkbox = true
        local status=$(echo "$issue" | grep -o ''"status":{[^}]*'' | grep -o ''"name":"[^"]*"'' | cut -d''"'' -f4)
        local checkbox=$(echo "$issue" | grep -o ''"customfield_approval_confirmation"[^}]*'' || echo "false")

        if [[ "$status" == "APPROVED" ]] && [[ "$checkbox" == *"true"* ]]; then
            echo "Approval granted with confirmation checkbox checked."
            local reviewer=$(echo "$issue" | grep -o ''"assignee":{[^}]*'' || echo "unknown")
            return 0
        fi

        sleep $poll_interval
        elapsed=$((elapsed + poll_interval))
    done

    echo "Approval timeout or not confirmed after $max_wait_seconds seconds."
    return 1
}

