"""  
Control: 916ec496-ff4e-4cb6-882d-d209c42dd731
Blast-radius limits for Okta onboarding in LangGraph.
Scaffold: Review, adapt, and integrate into your langgraph agent.
"""

from datetime import datetime
from google.cloud import firestore
from langchain.agents import tool
import logging

logger = logging.getLogger(__name__)

# TODO: Set your GCP Project ID
GCP_PROJECT_ID = "your-gcp-project-id"
# TODO: Set max users per onboarding run
MAX_USERS_PER_RUN = 50
# TODO: Set max daily pipeline executions
MAX_DAILY_PIPELINES = 10

db = firestore.Client(project=GCP_PROJECT_ID)

def check_blast_radius_users(users_to_provision: list) -> dict:
    """
    Pre-execution check: Validate user count does not exceed MAX_USERS_PER_RUN.
    Returns: {"allowed": bool, "message": str, "count": int}
    """
    count = len(users_to_provision)
    if count > MAX_USERS_PER_RUN:
        logger.error(
            f"Blast radius exceeded: {count} users > {MAX_USERS_PER_RUN} limit. "
            f"Halting provisioning."
        )
        return {
            "allowed": False,
            "message": f"Blast radius exceeded: {count} users exceeds limit of {MAX_USERS_PER_RUN}",
            "count": count
        }
    logger.info(f"User count within limits: {count}/{MAX_USERS_PER_RUN}")
    return {"allowed": True, "message": "User count within limits", "count": count}

def check_daily_pipeline_cap() -> dict:
    """
    Check daily pipeline execution cap. Increment counter and validate against max.
    Resets counter daily based on date in Firestore.
    Returns: {"allowed": bool, "message": str, "current_count": int, "max_allowed": int}
    """
    today = datetime.utcnow().date().isoformat()
    counter_doc = db.collection("onboarding_controls").document("daily_pipeline_count")
    
    transaction = db.transaction()
    
    @firestore.transactional
    def update_counter(txn):
        doc = counter_doc.get(transaction=txn)
        
        if not doc.exists:
            # Initialize if missing
            txn.set(counter_doc, {"count": 1, "date": today, "max_allowed": MAX_DAILY_PIPELINES})
            return {"allowed": True, "current_count": 1, "date": today}
        
        data = doc.to_dict()
        stored_date = data.get("date", "")
        current_count = data.get("count", 0)
        max_allowed = data.get("max_allowed", MAX_DAILY_PIPELINES)
        
        # Reset if date has changed
        if stored_date != today:
            txn.update(counter_doc, {"count": 1, "date": today})
            return {"allowed": True, "current_count": 1, "date": today}
        
        # Increment and check against cap
        new_count = current_count + 1
        if new_count > max_allowed:
            logger.warning(
                f"Daily pipeline cap exceeded: {new_count} pipelines > {max_allowed} limit. "
                f"Rejecting execution."
            )
            return {"allowed": False, "current_count": new_count, "max_allowed": max_allowed}
        
        txn.update(counter_doc, {"count": new_count})
        return {"allowed": True, "current_count": new_count, "max_allowed": max_allowed}
    
    result = update_counter(transaction)
    
    if result["allowed"]:
        logger.info(f"Pipeline execution allowed. Daily count: {result[''current_count'']}/{MAX_DAILY_PIPELINES}")
    else:
        logger.error(
            f"Daily pipeline cap exceeded: {result[''current_count'']} > {result[''max_allowed'']}. "
            f"Halting execution."
        )
    
    return result

def provision_okta_node(state: dict) -> dict:
    """
    LangGraph node: provision_okta
    Implements blast-radius checks before provisioning.
    
    State input: {"users_to_provision": [...], ...}
    State output: {"next_state": "blast_radius_exceeded" | "daily_cap_exceeded" | "proceed", ...}
    """
    users = state.get("users_to_provision", [])
    
    # Check 1: User count blast radius
    user_check = check_blast_radius_users(users)
    if not user_check["allowed"]:
        logger.error(f"Blast radius check failed: {user_check[''message'']}")
        # TODO: Emit alert to security team (e.g., via PagerDuty, Slack, Chronicle)
        return {**state, "next_state": "blast_radius_exceeded", "error": user_check["message"]}
    
    # Check 2: Daily pipeline execution cap
    daily_check = check_daily_pipeline_cap()
    if not daily_check["allowed"]:
        logger.error(f"Daily cap check failed: {daily_check}")
        # TODO: Emit alert to security team
        return {**state, "next_state": "daily_cap_exceeded", "error": "Daily pipeline limit reached"}
    
    # Both checks passed; proceed with provisioning
    logger.info("All blast-radius checks passed. Proceeding with provisioning.")
    return {**state, "next_state": "proceed", "blast_radius_check": "passed"}

EOF

echo "[OK] LangGraph configuration code generated: langgraph_blast_radius_config.py"
echo "[ACTION] Review and integrate the Python code into your LangGraph ''provision_okta'' node."
echo ""

# ==============================================================================
# PART 4: Monitoring & Alerting Setup (Chronicle Detection Query)
# ==============================================================================
# This outputs a detection query template for Google Chronicle to monitor
# blast-radius violations.

cat > chronicle_blast_radius_detection.sql << ''EOF''
# Control: 916ec496-ff4e-4cb6-882d-d209c42dd731
# Detection: Blast-radius limit violations in Okta agent
# TODO: Adapt data source names to match your Chronicle logs ingestion

SELECT
  eventTimestamp,
  sourceIpAddress,
  principalUser,
  eventType,
  eventDetail
FROM `zzz_cse.events`
WHERE
  eventType IN ("LangGraph.BlastRadiusExceeded", "LangGraph.DailyCapExceeded")
  OR (
    eventDetail CONTAINS "Blast radius exceeded"
    OR eventDetail CONTAINS "Daily pipeline cap exceeded"
  )
ORDER BY eventTimestamp DESC
LIMIT 1000
EOF

echo "[OK] Chronicle detection query template generated: chronicle_blast_radius_detection.sql"
echo ""

# ==============================================================================
