INSERT INTO control_items ("id", "org_id", "use_case_id", "pillar", "control", "why", "requirement", "status", "owner", "created_at", "framework_refs", "stack_implementation", "evidence", "assurance_test", "verification_status", "verification_mode", "verification_note", "verified_by", "verified_at", "artifact_type", "artifact_language", "artifact_filename", "artifact_content", "artifact_generated_at", "capability_id", "evidence_url") VALUES ('d114e9e1-e123-441e-8c34-cee2eed9c064', '00000000-0000-4000-a000-0000000000de', '159c61b4-30e3-40d4-88f0-f5a4b1d66b1b', 3, 'Implement credential scrubbing in LangGraph execution state, GCP infrastructure logs, and OpenAI API payloads to ensure temporary passwords, access tokens, and API keys are never persisted in plaintext.', 'Client confirmed credentials are currently present in plaintext in LangGraph state and logs; this creates a credential exposure vector in every system that captures execution data.', 'required', 'gap', NULL, '2026-06-08T11:06:43.005587+00:00', '{"eu_ai_act":"Art. 10 (data governance); Art. 15 (cybersecurity)","iso_42001":"A.8.2; A.8.4","owasp_llm":"LLM02 Sensitive Information Disclosure","nist_ai_rmf":"MANAGE 2.3; MANAGE 3.2"}'::jsonb, 'In the LangGraph graph definition, add a custom callback handler that intercepts all state writes and applies regex-based redaction for patterns matching temporary passwords, API keys, and tokens (e.g., replace matches with ''[REDACTED-CREDENTIAL]''). In GCP Cloud Logging, create a log exclusion filter or a DLP inspection job (using Cloud DLP with the CREDENTIALS and PASSWORD infoTypes) scoped to the GKE namespace running the agent. For OpenAI API calls, use a LangChain callback to sanitize the prompt payload before sending — strip credential values and replace with placeholder tokens that the downstream email tool re-injects from KMS at send time.', 'LangGraph callback configuration showing a secrets-scrubbing filter; GCP logging exclusion filter or DLP job configuration for credential patterns; sample log output demonstrating redaction.', 'Trigger a full onboarding run in a test environment; search GCP Cloud Logging, LangGraph trace output, and OpenAI API call logs for known test credential values and confirm zero plaintext matches.', 'not_checked', NULL, NULL, NULL, NULL, 'terraform', 'hcl', 'credential_scrubbing_gcp.tf', '# Credential Scrubbing in GCP Infrastructure & Cloud Logging
# Control ref: d114e9e1-e123-441e-8c34-cee2eed9c064
# Scaffold: Review and adapt environment-specific values before apply

terraform {
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 5.0"
    }
  }
}

# TODO: Set your GCP project ID
variable "gcp_project_id" {
  description = "GCP Project ID"
  type        = string
  default     = "<UNKNOWN>"
}

# TODO: Set the GKE namespace where the LangChain/LangGraph agent runs
variable "gke_namespace" {
  description = "GKE namespace for LangGraph agent"
  type        = string
  default     = "langchain-agents"
}

# TODO: Set the GKE cluster name
variable "gke_cluster_name" {
  description = "GKE cluster name"
  type        = string
  default     = "<UNKNOWN>"
}

# TODO: Set the GCP region
variable "gcp_region" {
  description = "GCP region"
  type        = string
  default     = "us-central1"
}

provider "google" {
  project = var.gcp_project_id
  region  = var.gcp_region
}

# ============================================================================
# 1. Cloud Logging Exclusion Filter
#    Excludes credentials and passwords from being logged in plaintext
# ============================================================================
resource "google_logging_project_exclusion" "credential_exclusion" {
  name            = "credential-scrubbing-exclusion"
  description     = "Exclude credential patterns from Cloud Logging to prevent plaintext credential persistence"
  project         = var.gcp_project_id
  
  # Exclusion filter: matches logs containing common credential patterns
  # This prevents sensitive data from being stored in Cloud Logging
  filter = join(" OR ", [
    "resource.type=k8s_container AND resource.labels.namespace_name=${var.gke_namespace}",
    "AND (",
    "  jsonPayload.password!=null",
    "  OR jsonPayload.api_key!=null",
    "  OR jsonPayload.access_token!=null",
    "  OR jsonPayload.temporary_password!=null",
    "  OR textPayload=~\"(password|api[_-]?key|access[_-]?token|temporary[_-]?password)\\s*[:=]\"",
    "  OR textPayload=~\"Bearer [A-Za-z0-9._-]{20,}\"",
    ")"
  ])
  
  # TODO: Review and adjust the exclusion filter regex patterns to match your actual credential formats
}

# ============================================================================
# 2. Cloud DLP Inspection Job
#    Detects and redacts credentials and passwords in logs
# ============================================================================
resource "google_data_loss_prevention_inspect_template" "credential_inspection" {
  parent       = "projects/${var.gcp_project_id}"
  description  = "Inspect template for credential and password detection in LangGraph logs"
  display_name = "Credential Redaction Inspection"
  
  inspect_config {
    # Predefined infoTypes for credential detection
    info_types {
      name = "CREDENTIAL"
    }
    info_types {
      name = "PASSWORD"
    }
    info_types {
      name = "API_KEY"
    }
    info_types {
      name = "OAUTH_TOKEN"
    }
    
    # Enable all predefined detectors
    include_quote = true
    min_likelihood = "POSSIBLE"
  }
}

resource "google_data_loss_prevention_deidentify_template" "credential_redaction" {
  parent       = "projects/${var.gcp_project_id}"
  description  = "Deidentify template to redact credentials and passwords"
  display_name = "Credential Redaction"
  
  deidentify_config {
    info_type_transformations {
      transformations {
        info_types {
          name = "CREDENTIAL"
        }
        info_types {
          name = "PASSWORD"
        }
        info_types {
          name = "API_KEY"
        }
        info_types {
          name = "OAUTH_TOKEN"
        }
        
        primitive_transformation {
          replace_with_info_type_config = {}
        }
      }
    }
  }
}

# ============================================================================
# 3. Cloud KMS Key for Re-injection of Scrubbed Credentials
#    Used by downstream tools (e.g., email) to re-inject real credentials
# ============================================================================
resource "google_kms_key_ring" "credential_keyring" {
  name     = "credential-management-keyring"
  location = var.gcp_region
  project  = var.gcp_project_id
}

resource "google_kms_crypto_key" "credential_key" {
  name            = "credential-scrubbing-key"
  key_ring        = google_kms_key_ring.credential_keyring.id
  rotation_period = "2592000s" # 30 days
  lifecycle {
    prevent_destroy = true
  }
}

# TODO: Bind the KMS key to the GKE service account so the agent can decrypt credentials for re-injection
resource "google_kms_crypto_key_iam_member" "gke_sa_decrypt" {
  crypto_key_id = google_kms_crypto_key.credential_key.id
  role          = "roles/cloudkms.cryptoKeyDecrypter"
  # TODO: Replace with your GKE service account email (e.g., "gke-agent-sa@PROJECT_ID.iam.gserviceaccount.com")
  member        = "serviceAccount:<TODO-GKE-SERVICE-ACCOUNT-EMAIL>"
}

# ============================================================================
# 4. Log Sink for Monitored Logging
#    Routes credential-scrubbed logs to Cloud Logging for audit
# ============================================================================
resource "google_logging_project_sink" "langchain_agent_sink" {
  name        = "langchain-agent-credential-audit-sink"
  description = "Routes LangChain agent logs (with credentials scrubbed) to Cloud Logging for audit"
  project     = var.gcp_project_id
  
  # Filter for LangChain agent logs from the specified GKE namespace
  filter = join(" AND ", [
    "resource.type=k8s_container",
    "resource.labels.namespace_name=${var.gke_namespace}",
    "resource.labels.pod_name=~\"langchain.*\""
  ])
  
  destination = "logging.googleapis.com/projects/${var.gcp_project_id}/logs/langchain-agent-audit"
  
  # TODO: Review filter to ensure it matches your actual LangChain pod naming convention
}

# ============================================================================
# 5. Monitoring Alert for Credential Detection in Logs
#    Alerts if credentials are detected in logs (indicates scrubbing failure)
# ============================================================================
resource "google_monitoring_alert_policy" "credential_leak_detection" {
  display_name = "Alert: Potential Credential Leak in Logs"
  project      = var.gcp_project_id
  combiner     = "OR"
  
  conditions {
    display_name = "Credential pattern detected in logs"
    condition_threshold {
      filter          = "resource.type=k8s_container AND resource.labels.namespace_name=${var.gke_namespace} AND (textPayload=~\"(password|api_key|access_token|temporary_password)\\s*[:=]|Bearer [A-Za-z0-9._-]{20,}\")"
      duration        = "60s"
      comparison      = "COMPARISON_GT"
      threshold_value = 0
      
      aggregations {
        alignment_period    = "60s"
        per_series_aligner  = "ALIGN_RATE"
      }
    }
  }
  
  notification_channels = [
    # TODO: Add notification channel IDs for your team (e.g., PagerDuty, email, Slack)
  ]
  
  # TODO: Replace with your actual notification channel resource IDs
  documentation {
    content   = "Credential pattern detected in LangChain agent logs. Review immediately to ensure credential scrubbing is working correctly."
    mime_type = "text/markdown"
  }
}

output "credential_key_id" {
  description = "Cloud KMS key ID for credential re-injection"
  value       = google_kms_crypto_key.credential_key.id
}

output "keyring_id" {
  description = "Cloud KMS keyring ID for credential management"
  value       = google_kms_key_ring.credential_keyring.id
}
